<!-- ══════════════════════════════════════════════
     TOPIC: COLECCIONES
══════════════════════════════════════════════ -->
<div id="colecciones" class="topic-section on">
  <div class="inner-nav">
    <button class="inner-btn on" onclick="showInner('colecciones','col1',this)">Introducción</button>
    <button class="inner-btn"   onclick="showInner('colecciones','col2',this)">Genéricos</button>
    <button class="inner-btn"   onclick="showInner('colecciones','col3',this)">Iteradores</button>
    <button class="inner-btn"   onclick="showInner('colecciones','col4',this)">List / Set / Queue</button>
    <button class="inner-btn"   onclick="showInner('colecciones','col5',this)">Map</button>
    <button class="inner-btn"   onclick="showInner('colecciones','col6',this)">Collections</button>
    <button class="inner-btn"   onclick="showInner('colecciones','col7',this)">Patrones</button>
  </div>

  <div id="col1" class="inner-section on">
    <div class="card">
      <div class="card-title">¿Qué son las colecciones?</div>
      <p style="font-size: 12.5px; color: var(--text2); line-height: 1.6; margin-bottom: 12px;">
        Las colecciones son estructuras dinámicas que permiten almacenar un número variable de elementos. A diferencia de los arrays (tamaño fijo), las colecciones pueden crecer o reducirse en tiempo de ejecución.
      </p>
      <p style="font-size: 12.5px; color: var(--text2); line-height: 1.6;">
        Todas las colecciones heredan de la interfaz <code>Collection</code>, que define operaciones básicas: añadir, quitar, comprobar existencia, recorrer, etc. Permite intercambiar datos entre distintos tipos de colecciones de forma fácil.
      </p>
      <pre style="margin-top: 12px;"><span class="cm">// Crear una lista a partir de un conjunto</span>
List&lt;String&gt; lista = <span class="kw">new</span> LinkedList&lt;&gt;(conjunto);

<span class="cm">// Cualquier colección se puede convertir a otra</span>
Set&lt;Integer&gt; numeros = <span class="kw">new</span> HashSet&lt;&gt;(lista);</pre>
    </div>
    <div class="card">
      <div class="card-title">Ventajas sobre arrays</div>
      <ul class="dots">
        <li><strong>Tamaño dinámico:</strong> Crecen según necesitan, sin declarar tamaño previo</li>
        <li><strong>Métodos útiles:</strong> add(), remove(), contains(), clear(), size()…</li>
        <li><strong>Intercambiables:</strong> Cambiar de ArrayList a LinkedList sin reescribir código</li>
        <li><strong>Tipadas:</strong> Con genéricos, el compilador valida tipos en tiempo de compilación</li>
      </ul>
    </div>
  </div>

  <div id="col2" class="inner-section">
    <div class="card">
      <div class="card-title">Tipos genéricos — sin ellos vs con ellos</div>
      <div class="grid2">
        <div>
          <span class="badge bc">SIN genéricos (antiguo)</span>
          <pre><span class="cm">// Cualquier tipo cabe → confuso</span>
ArrayList lista = <span class="kw">new</span> ArrayList();
lista.add(<span class="str">"texto"</span>);
lista.add(<span class="num">42</span>);      <span class="cm">// Se permite</span>

<span class="cm">// Necesita cast al obtener</span>
String s = (String) lista.get(<span class="num">0</span>);</pre>
        </div>
        <div>
          <span class="badge bt">CON genéricos (moderno)</span>
          <pre><span class="cm">// Solo Strings → seguro</span>
ArrayList&lt;String&gt; lista = 
    <span class="kw">new</span> ArrayList&lt;&gt;();
lista.add(<span class="str">"texto"</span>);
lista.add(<span class="num">42</span>);      <span class="cm">// ERROR ✓</span>

<span class="cm">// Sin cast necesario</span>
String s = lista.get(<span class="num">0</span>);</pre>
        </div>
      </div>
      <div class="tip">El compilador valida tipos en tiempo de compilación. Los genéricos no cambian el código generado, solo añaden comprobaciones de seguridad.</div>
    </div>
    <div class="card">
      <div class="card-title">Sintaxis genérica — uso correcto</div>
      <pre><span class="cm">// Declaración → especificar tipo de elementos</span>
List&lt;String&gt; palabras = <span class="kw">new</span> ArrayList&lt;&gt;();
Map&lt;String, Integer&gt; edades = <span class="kw">new</span> HashMap&lt;&gt;();
Set&lt;Integer&gt; unicos = <span class="kw">new</span> HashSet&lt;&gt;();

<span class="cm">// En métodos → genéricos en parámetros</span>
<span class="kw">public void</span> procesar(List&lt;Cliente&gt; clientes) { ... }
<span class="kw">public</span> Cliente obtener(Map&lt;String, Cliente&gt; mapa) { ... }

<span class="cm">// Genéricos de genéricos</span>
List&lt;List&lt;Integer&gt;&gt; matriz = <span class="kw">new</span> ArrayList&lt;&gt;();</pre>
    </div>
  </div>

  <div id="col3" class="inner-section">
    <div class="card">
      <div class="card-title">Iteradores — recorrer colecciones</div>
      <span class="badge bp">Forma clásica con Iterator</span>
      <pre><span class="cm">// 1. Obtener iterador</span>
Iterator&lt;String&gt; iter = lista.iterator();

<span class="cm">// 2. Recorrer con while</span>
<span class="kw">while</span> (iter.hasNext()) {
    String elemento = iter.next();
    System.out.println(elemento);
}

<span class="cm">// 3. Eliminar durante recorrido (seguro)</span>
<span class="kw">while</span> (iter.hasNext()) {
    String s = iter.next();
    <span class="kw">if</span> (s.length() &lt; <span class="num">3</span>) {
        iter.remove();  <span class="cm">// Elimina el actual</span>
    }
}</pre>
      <div class="warn">⚠ Nunca elimines de una colección con un bucle normal (for). Usa <code>iterator.remove()</code> o <code>removeIf()</code>.</div>
    </div>
    <div class="card">
      <div class="card-title">Formas modernas de recorrer</div>
      <div class="grid2">
        <div>
          <span class="badge bt">forEach (más limpio)</span>
          <pre><span class="kw">for</span> (String s : lista) {
    System.out.println(s);
}

<span class="cm">// NO permite modificar</span>
<span class="cm">// ni eliminar durante</span></pre>
        </div>
        <div>
          <span class="badge ba">forEach con método</span>
          <pre><span class="cm">// Más funcional (Java 8+)</span>
lista.forEach(s -&gt; 
    System.out.println(s)
);

<span class="cm">// O con referencia a método</span>
lista.forEach(System.out::println);</pre>
        </div>
      </div>
    </div>
  </div>

  <div id="col4" class="inner-section">
    <div class="card">
      <div class="card-title">Tipos principales — List, Set, Queue</div>
      <table class="stbl">
        <thead><tr><th>Tipo</th><th>Características</th><th>Implementaciones</th></tr></thead>
        <tbody>
          <tr><td>List</td><td>Ordenada por inserción, permite duplicados, acceso por índice</td><td>ArrayList, LinkedList</td></tr>
          <tr><td>Set</td><td>SIN orden definido, NO permite duplicados, rápido para búsqueda</td><td>HashSet, LinkedHashSet, TreeSet</td></tr>
          <tr><td>Queue</td><td>FIFO (primero entra, primero sale), orden de llegada</td><td>LinkedList, PriorityQueue</td></tr>
          <tr><td>Deque</td><td>Doble extremo, se puede acceder/quitar por ambos lados</td><td>LinkedList, ArrayDeque</td></tr>
        </tbody>
      </table>
    </div>
    <div class="card">
      <div class="card-title">ArrayList vs LinkedList</div>
      <div class="grid2">
        <div>
          <span class="badge bp">ArrayList</span>
          <pre><span class="cm">// Array interno redimensionable</span>
<span class="kw">List&lt;String&gt; lista = 
    <span class="kw">new</span> ArrayList&lt;&gt;();

<span class="cm">// ✓ Acceso rápido por índice</span>
<span class="cm">// ✗ Insertar/borrar lento</span>
<span class="cm">// Usar: lectura frecuente</span></pre>
        </div>
        <div>
          <span class="badge bt">LinkedList</span>
          <pre><span class="cm">// Lista enlazada (nodos)</span>
<span class="kw">List&lt;String&gt; lista = 
    <span class="kw">new</span> LinkedList&lt;&gt;();

<span class="cm">// ✗ Acceso lento por índice</span>
<span class="cm">// ✓ Insertar/borrar rápido</span>
<span class="cm">// Usar: colas, pilas</span></pre>
        </div>
      </div>
    </div>
    <div class="card">
      <div class="card-title">Set — evitar duplicados automáticamente</div>
      <pre><span class="cm">// HashSet → rápido, sin orden</span>
Set&lt;String&gt; unicos = <span class="kw">new</span> HashSet&lt;&gt;();
unicos.add(<span class="str">"a"</span>);
unicos.add(<span class="str">"b"</span>);
unicos.add(<span class="str">"a"</span>);  <span class="cm">// No se añade (ya existe)</span>
System.out.println(unicos.size());  <span class="cm">// 2</span>

<span class="cm">// TreeSet → ordenado, más lento pero automáticamente sort</span>
Set&lt;Integer&gt; ordenado = <span class="kw">new</span> TreeSet&lt;&gt;();
ordenado.add(<span class="num">3</span>); ordenado.add(<span class="num">1</span>); ordenado.add(<span class="num">2</span>);
<span class="cm">// Iterar imprime: 1, 2, 3</span></pre>
    </div>
    <div class="card">
      <div class="card-title">Queue — FIFO</div>
      <pre><span class="cm">// Crear cola</span>
Queue&lt;Integer&gt; cola = <span class="kw">new</span> LinkedList&lt;&gt;();

<span class="cm">// Encolar</span>
cola.add(<span class="num">1</span>);     <span class="cm">// o offer()</span>
cola.add(<span class="num">2</span>);

<span class="cm">// Desencolar</span>
<span class="kw">int</span> primero = cola.remove();  <span class="cm">// o poll() → null si vacía</span>
<span class="kw">int</span> frente  = cola.peek();     <span class="cm">// Ver sin quitar</span></pre>
    </div>
  </div>

  <div id="col5" class="inner-section">
    <div class="card">
      <div class="card-title">Map — pares clave-valor</div>
      <span class="badge bb">Tabla de doble entrada</span>
      <pre><span class="cm">// Crear mapa</span>
Map&lt;String, Integer&gt; edades = <span class="kw">new</span> HashMap&lt;&gt;();

<span class="cm">// Insertar (clave, valor)</span>
edades.put(<span class="str">"Juan"</span>, <span class="num">25</span>);
edades.put(<span class="str">"María"</span>, <span class="num">30</span>);

<span class="cm">// Obtener por clave</span>
<span class="kw">int</span> edad = edades.get(<span class="str">"Juan"</span>);    <span class="cm">// 25</span>
<span class="kw">int</span> desconocido = edades.get(<span class="str">"Bob"</span>);  <span class="cm">// null</span>

<span class="cm">// Comprobar existencia</span>
<span class="kw">if</span> (edades.containsKey(<span class="str">"Juan"</span>)) { ... }

<span class="cm">// Eliminar</span>
edades.remove(<span class="str">"Juan"</span>);

<span class="cm">// Recorrer claves</span>
<span class="kw">for</span> (String nombre : edades.keySet()) {
    System.out.println(nombre + <span class="str">": "</span> + edades.get(nombre));
}

<span class="cm">// Recorrer valores</span>
<span class="kw">for</span> (<span class="kw">int</span> e : edades.values()) {
    System.out.println(e);
}

<span class="cm">// Recorrer pares (Entry)</span>
<span class="kw">for</span> (Map.Entry&lt;String, Integer&gt; entrada : edades.entrySet()) {
    String clave = entrada.getKey();
    <span class="kw">int</span> valor = entrada.getValue();
}</pre>
      <div class="tip">Usa <code>entrySet()</code> para recorrer, es más eficiente que <code>keySet()</code> + <code>get()</code>.</div>
    </div>
    <div class="card">
      <div class="card-title">HashMap vs TreeMap</div>
      <div class="mref">
        <div class="mref-row"><span class="mref-name">HashMap</span><span class="mref-desc">Rápido, sin orden. Usa función hash de las claves.</span></div>
        <div class="mref-row"><span class="mref-name">TreeMap</span><span class="mref-desc">Ordenado alfabéticamente, más lento. Las claves deben ser Comparable.</span></div>
      </div>
    </div>
  </div>

  <div id="col6" class="inner-section">
    <div class="card">
      <div class="card-title">Clase Collections — utilidades estáticas</div>
      <span class="badge ba">Similar a Arrays, pero para colecciones</span>
      <pre><span class="cm">// Ordenar una lista</span>
Collections.sort(lista);                    <span class="cm">// orden natural</span>
Collections.sort(lista, comparador);        <span class="cm">// con comparador</span>
Collections.sort(lista, Collections.reverseOrder()); <span class="cm">// inverso</span>

<span class="cm">// Barajar</span>
Collections.shuffle(lista);

<span class="cm">// Busca binaria (requiere lista ordenada)</span>
<span class="kw">int</span> indice = Collections.binarySearch(lista, elemento);

<span class="cm">// Max / Min</span>
Integer maximo = Collections.max(numeros);
Integer minimo = Collections.min(numeros);

<span class="cm">// Llenar</span>
Collections.fill(lista, <span class="str">"valor"</span>);

<span class="cm">// Contar occurrencias</span>
<span class="kw">int</span> veces = Collections.frequency(lista, elemento);</pre>
    </div>
  </div>

  <div id="col7" class="inner-section">
    <div class="card">
      <div class="card-title">Filtrar una lista → removeIf()</div>
      <pre><span class="cm">// Eliminar todos menores de 18</span>
lista.removeIf(p -&gt; p.getEdad() &lt; <span class="num">18</span>);

<span class="cm">// Eliminar strings vacíos</span>
palabras.removeIf(String::isEmpty);</pre>
    </div>
    <div class="card">
      <div class="card-title">Contar elementos que cumplen condición</div>
      <pre><span class="cm">// Con stream (Java 8+)</span>
<span class="kw">long</span> mayores = empleados.stream()
    .filter(e -&gt; e.getEdad() &gt; <span class="num">30</span>)
    .count();

<span class="cm">// Con iterador clásico</span>
<span class="kw">int</span> contador = <span class="num">0</span>;
<span class="kw">for</span> (Empleado e : empleados) {
    <span class="kw">if</span> (e.getEdad() &gt; <span class="num">30</span>) contador++;
}</pre>
    </div>
    <div class="card">
      <div class="card-title">Buscar un elemento</div>
      <pre><span class="cm">// En Set → contains() es O(1)</span>
<span class="kw">if</span> (conjunto.contains(elemento)) { ... }

<span class="cm">// En List → contains() es O(n), pero cómodo</span>
<span class="kw">if</span> (lista.contains(elemento)) { ... }

<span class="cm">// Buscar con condición</span>
Empleado encontrado = empleados.stream()
    .filter(e -&gt; e.getNombre().equals(<span class="str">"Juan"</span>))
    .findFirst()
    .orElse(<span class="kw">null</span>);</pre>
    </div>
  </div>
</div><!-- /colecciones -->


<!-- ══════════════════════════════════════════════
     TOPIC: FECHAS Y HORAS
══════════════════════════════════════════════ -->
<div id="fechas" class="topic-section">
  <div class="inner-nav">
    <button class="inner-btn on" onclick="showInner('fechas','f1',this)">LocalDate</button>
    <button class="inner-btn"   onclick="showInner('fechas','f2',this)">LocalTime</button>
    <button class="inner-btn"   onclick="showInner('fechas','f3',this)">LocalDateTime</button>
    <button class="inner-btn"   onclick="showInner('fechas','f4',this)">Period / Duration</button>
    <button class="inner-btn"   onclick="showInner('fechas','f5',this)">Formatear</button>
    <button class="inner-btn"   onclick="showInner('fechas','f6',this)">Comparar</button>
  </div>

  <div id="f1" class="inner-section on">
    <div class="card">
      <div class="card-title">LocalDate — solo fecha, sin hora</div>
      <pre><span class="kw">import</span> java.time.*;
<span class="kw">import</span> java.time.format.*;

<span class="cm">// Hoy</span>
LocalDate hoy = LocalDate.now();

<span class="cm">// Fecha específica</span>
LocalDate navidad = LocalDate.of(<span class="num">2024</span>, <span class="num">12</span>, <span class="num">25</span>);

<span class="cm">// Parsear desde String</span>
