<span class="cm">// Obtener componentes</span>
<span class="kw">int</span> año = hoy.getYear();
<span class="kw">int</span> mes = hoy.getMonthValue();      <span class="cm">// 1-12</span>
<span class="kw">int</span> dia = hoy.getDayOfMonth();

