      <div class="card-title">LocalDateTime — fecha + hora</div>
      <pre><span class="cm">// Ahora (fecha y hora)</span>
LocalDateTime ahorita = LocalDateTime.now();

<span class="cm">// Fecha y hora específicas</span>
LocalDateTime reunion = LocalDateTime.of(<span class="num">2024</span>, <span class="num">12</span>, <span class="num">25</span>, <span class="num">10</span>, <span class="num">30</span>);

