LocalDate hoy = LocalDate.now();
Period edad = inicio.until(hoy);

System.out.println(<span class="str">"Años: "</span> + edad.getYears());
System.out.println(<span class="str">"Meses: "</span> + edad.getMonths());
System.out.println(<span class="str">"Días: "</span> + edad.getDays());</pre>
