<div id="streams" class="topic-section">
  <div class="inner-nav">
    <button class="inner-btn on" onclick="showInner('streams','s1',this)">Clases internas</button>
    <button class="inner-btn"   onclick="showInner('streams','s2',this)">Lambdas</button>
