  <div id="sim1" class="inner-section on">
    <div class="card">
      <div class="card-title">Ejercicio: Buscar palabras en Sopa de Letras</div>
      <p style="font-size: 12.5px; color: var(--text2); margin-bottom: 12px;">
        Dada una sopa de letras (char[][] sopaDeLetras) y un diccionario (List&lt;String&gt; diccionario), buscar cada palabra 
        en cuatro direcciones: horizontal derecha, horizontal izquierda, vertical arriba, vertical abajo.
      </p>
      <pre><span class="cm">// Métodos a implementar</span>
<span class="kw">public static int</span>[] buscarHorizontalDerecha(
    <span class="kw">char</span>[][] sopa, String palabra) { ... }

<span class="kw">public static int</span>[] buscarHorizontalIzquierda(
    <span class="kw">char</span>[][] sopa, String palabra) { ... }

<span class="kw">public static int</span>[] buscarVerticalAbajo(
    <span class="kw">char</span>[][] sopa, String palabra) { ... }

<span class="kw">public static int</span>[] buscarVerticalArriba(
    <span class="kw">char</span>[][] sopa, String palabra) { ... }

<span class="cm">// Método principal</span>
<span class="kw">public static void</span> buscar(
    <span class="kw">char</span>[][] sopa, List&lt;String&gt; diccionario) {
    <span class="kw">for</span> (String palabra : diccionario) {
        <span class="kw">int</span>[] posH_der = buscarHorizontalDerecha(sopa, palabra);
        <span class="kw">int</span>[] posH_izq = buscarHorizontalIzquierda(sopa, palabra);
        <span class="kw">int</span>[] posV_aba = buscarVerticalAbajo(sopa, palabra);
        <span class="kw">int</span>[] posV_arr = buscarVerticalArriba(sopa, palabra);

        <span class="cm">// Mostrar resultados</span>
        <span class="kw">if</span> (posH_der != <span class="kw">null</span>)
            System.out.println(palabra + <span class="str">" derecha: "</span> + 
                Arrays.toString(posH_der));
        <span class="cm">// ... igual para otros</span>
    }
}</pre>
    </div>
    <div class="card">
      <div class="card-title">Pistas de implementación</div>
      <ul class="dots">
        <li><strong>Horizontal derecha:</strong> Recorrer cada fila, buscar palabra de izquierda a derecha</li>
        <li><strong>Horizontal izquierda:</strong> Recorrer cada fila, buscar palabra invertida</li>
        <li><strong>Vertical abajo:</strong> Recorrer cada columna, buscar palabra de arriba a abajo</li>
        <li><strong>Vertical arriba:</strong> Recorrer cada columna, buscar palabra invertida</li>
        <li>Devolver null si no se encuentra</li>
        <li>Devolver [fila, columna] del inicio de la palabra si la encuentra</li>
      </ul>
    </div>
  </div>

  <div id="sim2" class="inner-section">
    <div class="card">
      <div class="card-title">Diagrama UML — Persona, Empleado, Empresa, Contrato</div>
      <p style="font-size: 12.5px; color: var(--text2); margin-bottom: 12px;">
        Implementar las siguientes clases según el diagrama:
      </p>
      <div class="mref">
        <div class="mref-row"><span class="mref-name">Persona (abstract)</span><span class="mref-desc">dni, nombre, apellidos, fechaNacimiento. Comparable por apellidos+nombre.</span></div>
        <div class="mref-row"><span class="mref-name">Empleado extends Persona</span><span class="mref-desc">Añade especialidad. equals() por dni. toString() incluye especialidad.</span></div>
        <div class="mref-row"><span class="mref-name">Empresa</span><span class="mref-desc">nombre, tipoNegocio. equals() por nombre. Lista de Contratos.</span></div>
        <div class="mref-row"><span class="mref-name">Contrato</span><span class="mref-desc">trabajador, empresa, fechaAlta, fechaBaja (null si activo), salario.</span></div>
      </div>
      <pre style="margin-top: 12px;"><span class="cm">// Ejemplo de equals() en Persona</span>
<span class="kw">@Override</span>
<span class="kw">public boolean</span> equals(Object obj) {
    <span class="kw">if</span> (!(obj <span class="kw">instanceof</span> Persona)) <span class="kw">return false</span>;
    <span class="kw">return</span> <span class="kw">this</span>.dni.equals(((Persona) obj).dni);
}

<span class="cm">// Ejemplo de compareTo (por apellidos + nombre)</span>
<span class="kw">@Override</span>
<span class="kw">public int</span> compareTo(Persona otra) {
    <span class="kw">int</span> apellidosCmp = <span class="kw">this</span>.apellidos
        .compareTo(otra.apellidos);
    <span class="kw">if</span> (apellidosCmp != <span class="num">0</span>) <span class="kw">return</span> apellidosCmp;
    <span class="kw">return this</span>.nombre.compareTo(otra.nombre);
}</pre>
    </div>
    <div class="card">
      <div class="card-title">toString() de Contrato</div>
      <pre><span class="cm">// Formato: "Trabajador (dni) - Empresa - Salario - Fecha inicio - Fecha fin"</span>
<span class="cm">// Si fechaBaja es null → mostrar solo fecha inicio</span>
<span class="cm">// Ejemplo: "Juan García (12345678A) - TechCorp - 2000€ - 10/12/2005 - 30/06/2007"</span>
<span class="cm">//         "María López (98765432B) - TechCorp - 1800€ - 15/03/2015 - "</span>

<span class="kw">@Override</span>
<span class="kw">public</span> String toString() {
    DateTimeFormatter fmt = DateTimeFormatter.ofPattern(<span class="str">"dd/MM/yyyy"</span>);
    String fin = (fechaBaja == <span class="kw">null</span>) ? <span class="str">"en activo"</span> 
                                        : fechaBaja.format(fmt);
    <span class="kw">return</span> trabajador.getNombre() + <span class="str">" - "</span> 
         + empresa.getNombre() + <span class="str">" - "</span>
         + salario + <span class="str">"€ - "</span>
         + fechaAlta.format(fmt) + <span class="str">" - "</span> + fin;
}</pre>
    </div>
  </div>

  <div id="sim3" class="inner-section">
    <div class="card">
      <div class="card-title">Consultas a implementar (con Streams)</div>
      <pre><span class="cm">// 1. Número de empleados con más de 1 contrato extinguido</span>
<span class="kw">long</span> empleadosConMasDeUnExtinguido = empleados.stream()
    .filter(e -&gt; e.getContratos().stream()
        .filter(c -&gt; c.getFechaBaja() != <span class="kw">null</span>)
        .count() &gt; <span class="num">1</span>)
    .count();

<span class="cm">// 2. Trabajador con mayor salario en una fecha dada</span>
LocalDate fecha = LocalDate.of(<span class="num">2020</span>, <span class="num">6</span>, <span class="num">15</span>);
Empleado mejorPagado = empleados.stream()
    .flatMap(e -&gt; e.getContratos().stream()
        .filter(c -&gt; esActivoEnFecha(c, fecha))
        .map(c -&gt; new AbstractMap.SimpleEntry&lt;&gt;(e, c)))
    .max(Comparator.comparingDouble(
        e -&gt; e.getValue().getSalario()))
    .map(AbstractMap.SimpleEntry::getKey)
    .orElse(<span class="kw">null</span>);

<span class="cm">// 3. Listado de empleados en empresa X en fecha Y</span>
Empresa empresa = empresas.get(<span class="num">0</span>);
LocalDate fecha = LocalDate.of(<span class="num">2022</span>, <span class="num">3</span>, <span class="num">15</span>);
List&lt;Empleado&gt; trabajandoEnEsa = empleados.stream()
    .filter(e -&gt; e.getContratos().stream()
        .anyMatch(c -&gt; c.getEmpresa().equals(empresa) 
                    && esActivoEnFecha(c, fecha)))
    .sorted()
    .collect(Collectors.toList());

<span class="cm">// 4. Suma de salarios en empresa X en fecha Y</span>
<span class="kw">double</span> totalSalarios = empleados.stream()
    .flatMap(e -&gt; e.getContratos().stream()
        .filter(c -&gt; c.getEmpresa().equals(empresa)
                   && esActivoEnFecha(c, fecha))
        .map(c -&gt; c.getSalario()))
    .mapToDouble(Double::doubleValue)
    .sum();

<span class="cm">// 5. Empleado más viejo en empresa X en fecha Y</span>
Empleado masViejo = empleados.stream()
    .filter(e -&gt; e.getContratos().stream()
        .anyMatch(c -&gt; c.getEmpresa().equals(empresa)
                    && esActivoEnFecha(c, fecha)))
    .min(Comparator.comparing(Persona::getFechaNacimiento))
    .orElse(<span class="kw">null</span>);

<span class="cm">// Método auxiliar</span>
<span class="kw">private static boolean</span> esActivoEnFecha(Contrato c, LocalDate fecha) {
    <span class="kw">return</span> !fecha.isBefore(c.getFechaAlta()) &&
           (c.getFechaBaja() == <span class="kw">null</span> || fecha.isBefore(c.getFechaBaja()));
}</pre>
    </div>
    <div class="card">
      <div class="card-title">Datos de prueba</div>
      <pre><span class="cm">// 2 empresas</span>
Empresa google = <span class="kw">new</span> Empresa(<span class="str">"Google"</span>, <span class="str">"Tecnología"</span>);
Empresa amazon = <span class="kw">new</span> Empresa(<span class="str">"Amazon"</span>, <span class="str">"E-commerce"</span>);

<span class="cm">// 4 empleados</span>
Empleado juan = <span class="kw">new</span> Empleado(
    <span class="str">"12345678A"</span>, <span class="str">"Juan"</span>, <span class="str">"García"</span>,
    LocalDate.of(<span class="num">1990</span>, <span class="num">3</span>, <span class="num">15</span>), <span class="str">"Backend"</span>);

Empleado maria = <span class="kw">new</span> Empleado(
    <span class="str">"98765432B"</span>, <span class="str">"María"</span>, <span class="str">"López"</span>,
    LocalDate.of(<span class="num">1992</span>, <span class="num">7</span>, <span class="num">22</span>), <span class="str">"Frontend"</span>);

<span class="cm">// ... más empleados</span>

<span class="cm">// Contratos variados</span>
google.agregarContrato(<span class="kw">new</span> Contrato(
    juan, google,
    LocalDate.of(<span class="num">2018</span>, <span class="num">1</span>, <span class="num">15</span>),
    LocalDate.of(<span class="num">2021</span>, <span class="num">6</span>, <span class="num">30</span>),  <span class="cm">// extinguido</span>
    <span class="num">2500</span>
));</pre>
    </div>
  </div>
</div><!-- /simulacro -->

<script>
function showTopic(id, btn) {
  document.querySelectorAll('.topic-section').forEach(s => s.classList.remove('on'));
  document.querySelectorAll('.topic-btn').forEach(b => b.classList.remove('on'));
  document.getElementById(id).classList.add('on');
  btn.classList.add('on');
}

function showInner(topic, id, btn) {
  const parent = document.getElementById(topic);
  parent.querySelectorAll('.inner-section').forEach(s => s.classList.remove('on'));
  parent.querySelectorAll('.inner-btn').forEach(b => b.classList.remove('on'));
  document.getElementById(id).classList.add('on');
  btn.classList.add('on');
}
</script>
</body>
</html>", "message": "Añadir Tema 12 (Colecciones), Tema 13 (Streams) y Simulacro de Examen Final"}

{"owner": "carlosruizgarrido", "repo": "guia_java", "path": "guia_java_ampliada.html", "content": "<!DOCTYPE html>
<html lang="es">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Guía Java — Examen</title>
<style>
  :root {
    --bg: #0f0f13;
    --bg2: #16161d;
    --bg3: #1e1e28;
    --bg4: #25252f;
    --border: #2e2e3a;
    --border2: #3a3a4a;
    --text: #e8e6f0;
    --text2: #9896a8;
    --text3: #5f5d70;
    --purple: #a78bfa;
    --purple-bg: #1e1a35;
    --purple-border: #4c3d8a;
    --teal: #34d399;
    --teal-bg: #0d2620;
    --teal-border: #1a5c48;
    --amber: #fbbf24;
    --amber-bg: #1f1a0a;
    --amber-border: #5c4a0a;
    --coral: #f87171;
    --coral-bg: #1f0f0f;
    --coral-border: #5c2020;
    --blue: #60a5fa;
    --blue-bg: #0d1a2e;
    --blue-border: #1a3a5c;
    --kw: #c084fc;
    --cm: #4a4860;
    --str: #34d399;
    --num: #f87171;
    --fn: #60a5fa;
  }

  * { box-sizing: border-box; margin: 0; padding: 0; }

  body {
    background: var(--bg);
    color: var(--text);
    font-family: 'Segoe UI', system-ui, sans-serif;
    font-size: 14px;
    line-height: 1.6;
  }

  header {
    background: var(--bg2);
    border-bottom: 1px solid var(--border);
    padding: 16px 24px;
    display: flex;
    align-items: center;
    gap: 16px;
    position: sticky;
    top: 0;
    z-index: 100;
    flex-wrap: wrap;
  }
  header h1 { font-size: 16px; font-weight: 600; color: var(--text); letter-spacing: .02em; }
  header .chip {
    background: var(--purple-bg);
    border: 1px solid var(--purple-border);
    color: var(--purple);
    font-size: 11px;
    padding: 2px 8px;
    border-radius: 20px;
    font-weight: 500;
  }

  .topic-nav {
    background: var(--bg2);
    border-bottom: 1px solid var(--border);
    padding: 0 24px;
    display: flex;
    gap: 0;
    overflow-x: auto;
  }
  .topic-btn {
    background: none;
    border: none;
    border-bottom: 2px solid transparent;
    color: var(--text2);
    font-size: 13px;
    font-weight: 500;
    padding: 12px 18px;
    cursor: pointer;
    transition: all .15s;
    white-space: nowrap;
  }
  .topic-btn:hover { color: var(--text); }
  .topic-btn.on { color: var(--purple); border-bottom-color: var(--purple); }

  .topic-section { display: none; }
  .topic-section.on { display: block; }

  .inner-nav {
    padding: 16px 24px 0;
    display: flex;
    gap: 6px;
    flex-wrap: wrap;
  }
  .inner-btn {
    background: var(--bg3);
    border: 1px solid var(--border);
    color: var(--text2);
    font-size: 12px;
    padding: 5px 13px;
    border-radius: 20px;
    cursor: pointer;
    transition: all .15s;
  }
  .inner-btn:hover { border-color: var(--border2); color: var(--text); }
  .inner-btn.on { background: var(--purple-bg); border-color: var(--purple-border); color: var(--purple); font-weight: 500; }

  .inner-section { display: none; padding: 16px 24px 32px; }
  .inner-section.on { display: block; }

  .card {
    background: var(--bg2);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 16px 18px;
    margin-bottom: 12px;
  }
  .card-title {
    font-size: 10.5px;
    font-weight: 600;
    color: var(--text3);
    text-transform: uppercase;
    letter-spacing: .08em;
    margin-bottom: 10px;
  }
  .grid2 { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
  .grid3 { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 8px; }

  pre {
    background: var(--bg);
    border: 1px solid var(--border);
    border-radius: 8px;
    padding: 12px 14px;
    font-family: 'Cascadia Code', 'Fira Code', 'Consolas', monospace;
    font-size: 12.5px;
    overflow-x: auto;
    line-height: 1.65;
    white-space: pre;
    margin-top: 8px;
  }
  .kw  { color: var(--kw); font-weight: 500; }
  .cm  { color: var(--cm); font-style: italic; }
  .str { color: var(--str); }
  .num { color: var(--num); }
  .fn  { color: var(--fn); }

  .badge {
    display: inline-block;
    font-size: 11px;
    font-weight: 500;
    padding: 2px 9px;
    border-radius: 20px;
    margin-bottom: 8px;
  }
  .bp { background: var(--purple-bg); color: var(--purple); border: 1px solid var(--purple-border); }
  .bt { background: var(--teal-bg);   color: var(--teal);   border: 1px solid var(--teal-border); }
  .ba { background: var(--amber-bg);  color: var(--amber);  border: 1px solid var(--amber-border); }
  .bc { background: var(--coral-bg);  color: var(--coral);  border: 1px solid var(--coral-border); }
  .bb { background: var(--blue-bg);   color: var(--blue);   border: 1px solid var(--blue-border); }

  .tip  { background: var(--teal-bg);  border-left: 3px solid var(--teal);  color: #7ee8c0; padding: 8px 12px; border-radius: 0 6px 6px 0; font-size: 12.5px; margin-top: 10px; }
  .warn { background: var(--amber-bg); border-left: 3px solid var(--amber); color: #f0c060; padding: 8px 12px; border-radius: 0 6px 6px 0; font-size: 12.5px; margin-top: 8px; }
  .err  { background: var(--coral-bg); border-left: 3px solid var(--coral); color: #f09090; padding: 8px 12px; border-radius: 0 6px 6px 0; font-size: 12.5px; margin-top: 8px; }
  .info { background: var(--blue-bg);  border-left: 3px solid var(--blue);  color: #90c0f0; padding: 8px 12px; border-radius: 0 6px 6px 0; font-size: 12.5px; margin-top: 8px; }

  code {
    font-family: 'Cascadia Code','Fira Code','Consolas',monospace;
    font-size: 12px;
    background: var(--bg4);
    color: var(--purple);
    padding: 1px 6px;
    border-radius: 4px;
  }
  ul.dots { list-style: none; display: flex; flex-direction: column; gap: 5px; margin-top: 8px; }
  ul.dots li { font-size: 12.5px; color: var(--text2); padding-left: 16px; position: relative; line-height: 1.5; }
  ul.dots li::before { content: "›"; position: absolute; left: 0; color: var(--purple); font-weight: 700; }

  .mref { display: flex; flex-direction: column; gap: 6px; }
  .mref-row { display: flex; gap: 12px; padding: 7px 10px; background: var(--bg3); border-radius: 7px; border: 1px solid var(--border); }
  .mref-name { font-family: monospace; font-size: 12px; color: var(--blue); font-weight: 500; min-width: 240px; }
  .mref-desc { font-size: 12px; color: var(--text2); }

  .stbl { width: 100%; border-collapse: collapse; font-size: 12.5px; margin-top: 6px; }
  .stbl th { text-align: left; color: var(--text3); font-size: 10.5px; text-transform: uppercase; letter-spacing: .06em; padding: 6px 10px; border-bottom: 1px solid var(--border); font-weight: 600; }
  .stbl td { padding: 6px 10px; border-bottom: 1px solid var(--border); color: var(--text2); vertical-align: top; }
  .stbl td:first-child { font-family: monospace; font-size: 12px; color: var(--blue); white-space: nowrap; }
  .stbl tr:last-child td { border-bottom: none; }
  .stbl tr:hover td { background: var(--bg3); }

  @media (max-width: 600px) {
    .grid2, .grid3 { grid-template-columns: 1fr; }
    .mref-row { flex-direction: column; gap: 4px; }
    .mref-name { min-width: unset; }
  }
</style>
</head>
<body>

<header>
  <h1>Guía Java — Examen</h1>
  <span class="chip">Arrays</span>
  <span class="chip" style="background:var(--teal-bg);border-color:var(--teal-border);color:var(--teal)">Cadenas</span>
  <span class="chip" style="background:var(--amber-bg);border-color:var(--amber-border);color:var(--amber)">Clases / POO</span>
  <span class="chip" style="background:var(--blue-bg);border-color:var(--blue-border);color:var(--blue)">Herencia</span>
  <span class="chip" style="background:var(--teal-bg);border-color:var(--teal-border);color:var(--teal);opacity:.85">Interfaces</span>
  <span class="chip" style="background:var(--coral-bg);border-color:var(--coral-border);color:var(--coral)">Ficheros</span>
  <span class="chip" style="background:var(--blue-bg);border-color:var(--blue-border);color:var(--blue);opacity:.85">Binarios</span>
  <span class="chip" style="background:var(--purple-bg);border-color:var(--purple-border);color:var(--purple)">Colecciones</span>
  <span class="chip" style="background:var(--teal-bg);border-color:var(--teal-border);color:var(--teal)">Streams</span>
</header>

<nav class="topic-nav">
  <button class="topic-btn on" onclick="showTopic('colecciones',this)">Colecciones</button>
  <button class="topic-btn"    onclick="showTopic('fechas',this)">Fechas / Horas</button>
  <button class="topic-btn"    onclick="showTopic('streams',this)">Streams / Lambdas</button>
  <button class="topic-btn"    onclick="showTopic('simulacro',this)">Simulacro</button>
</nav>


<!-- ══════════════════════════════════════════════
     TOPIC: COLECCIONES
══════════════════════════════════════════════ -->
<div id="colecciones" class="topic-section on">
  <div class="inner-nav">
    <button class="inner-btn on" onclick="showInner('colecciones','col1',this)">Introducción</button>
    <button class="inner-btn"   onclick="showInner('colecciones','col2',this)">Genéricos</button>
    <button class="inner-btn"   onclick="showInner('colecciones','col3',this)">Iteradores</button>
    <button class="inner-btn"   onclick="showInner('colecciones','col4',this)">List / Set / Queue</button>
    <button class="inner-btn"   onclick="showInner('colecciones','col5',this)">Map</button>
    <button class="inner-btn"   onclick="showInner('colecciones','col6',this)">Collections</button>
    <button class="inner-btn"   onclick="showInner('colecciones','col7',this)">Patrones</button>
  </div>

  <div id="col1" class="inner-section on">
    <div class="card">
      <div class="card-title">¿Qué son las colecciones?</div>
      <p style="font-size: 12.5px; color: var(--text2); line-height: 1.6; margin-bottom: 12px;">
        Las colecciones son estructuras dinámicas que permiten almacenar un número variable de elementos. A diferencia de los arrays (tamaño fijo), las colecciones pueden crecer o reducirse en tiempo de ejecución.
      </p>
      <p style="font-size: 12.5px; color: var(--text2); line-height: 1.6;">
        Todas las colecciones heredan de la interfaz <code>Collection</code>, que define operaciones básicas: añadir, quitar, comprobar existencia, recorrer, etc. Permite intercambiar datos entre distintos tipos de colecciones de forma fácil.
      </p>
      <pre style="margin-top: 12px;"><span class="cm">// Crear una lista a partir de un conjunto</span>
List&lt;String&gt; lista = <span class="kw">new</span> LinkedList&lt;&gt;(conjunto);

<span class="cm">// Cualquier colección se puede convertir a otra</span>
Set&lt;Integer&gt; numeros = <span class="kw">new</span> HashSet&lt;&gt;(lista);</pre>
    </div>
    <div class="card">
      <div class="card-title">Ventajas sobre arrays</div>
      <ul class="dots">
        <li><strong>Tamaño dinámico:</strong> Crecen según necesitan, sin declarar tamaño previo</li>
        <li><strong>Métodos útiles:</strong> add(), remove(), contains(), clear(), size()…</li>
        <li><strong>Intercambiables:</strong> Cambiar de ArrayList a LinkedList sin reescribir código</li>
        <li><strong>Tipadas:</strong> Con genéricos, el compilador valida tipos en tiempo de compilación</li>
      </ul>
    </div>
  </div>

  <div id="col2" class="inner-section">
    <div class="card">
      <div class="card-title">Tipos genéricos — sin ellos vs con ellos</div>
      <div class="grid2">
        <div>
          <span class="badge bc">SIN genéricos (antiguo)</span>
          <pre><span class="cm">// Cualquier tipo cabe → confuso</span>
ArrayList lista = <span class="kw">new</span> ArrayList();
lista.add(<span class="str">"texto"</span>);
lista.add(<span class="num">42</span>);      <span class="cm">// Se permite</span>

<span class="cm">// Necesita cast al obtener</span>
String s = (String) lista.get(<span class="num">0</span>);</pre>
        </div>
        <div>
          <span class="badge bt">CON genéricos (moderno)</span>
          <pre><span class="cm">// Solo Strings → seguro</span>
ArrayList&lt;String&gt; lista = 
    <span class="kw">new</span> ArrayList&lt;&gt;();
lista.add(<span class="str">"texto"</span>);
lista.add(<span class="num">42</span>);      <span class="cm">// ERROR ✓</span>

<span class="cm">// Sin cast necesario</span>
String s = lista.get(<span class="num">0</span>);</pre>
        </div>
      </div>
      <div class="tip">El compilador valida tipos en tiempo de compilación. Los genéricos no cambian el código generado, solo añaden comprobaciones de seguridad.</div>
    </div>
    <div class="card">
      <div class="card-title">Sintaxis genérica — uso correcto</div>
      <pre><span class="cm">// Declaración → especificar tipo de elementos</span>
List&lt;String&gt; palabras = <span class="kw">new</span> ArrayList&lt;&gt;();
Map&lt;String, Integer&gt; edades = <span class="kw">new</span> HashMap&lt;&gt;();
Set&lt;Integer&gt; unicos = <span class="kw">new</span> HashSet&lt;&gt;();

<span class="cm">// En métodos → genéricos en parámetros</span>
<span class="kw">public void</span> procesar(List&lt;Cliente&gt; clientes) { ... }
<span class="kw">public</span> Cliente obtener(Map&lt;String, Cliente&gt; mapa) { ... }

<span class="cm">// Genéricos de genéricos</span>
List&lt;List&lt;Integer&gt;&gt; matriz = <span class="kw">new</span> ArrayList&lt;&gt;();</pre>
    </div>
  </div>

  <div id="col3" class="inner-section">
    <div class="card">
      <div class="card-title">Iteradores — recorrer colecciones</div>
      <span class="badge bp">Forma clásica con Iterator</span>
      <pre><span class="cm">// 1. Obtener iterador</span>
Iterator&lt;String&gt; iter = lista.iterator();

<span class="cm">// 2. Recorrer con while</span>
<span class="kw">while</span> (iter.hasNext()) {
    String elemento = iter.next();
    System.out.println(elemento);
}

<span class="cm">// 3. Eliminar durante recorrido (seguro)</span>
<span class="kw">while</span> (iter.hasNext()) {
    String s = iter.next();
    <span class="kw">if</span> (s.length() &lt; <span class="num">3</span>) {
        iter.remove();  <span class="cm">// Elimina el actual</span>
    }
}</pre>
      <div class="warn">⚠ Nunca elimines de una colección con un bucle normal (for). Usa <code>iterator.remove()</code> o <code>removeIf()</code>.</div>
    </div>
    <div class="card">
      <div class="card-title">Formas modernas de recorrer</div>
      <div class="grid2">
        <div>
          <span class="badge bt">forEach (más limpio)</span>
          <pre><span class="kw">for</span> (String s : lista) {
    System.out.println(s);
}

<span class="cm">// NO permite modificar</span>
<span class="cm">// ni eliminar durante</span></pre>
        </div>
        <div>
          <span class="badge ba">forEach con método</span>
          <pre><span class="cm">// Más funcional (Java 8+)</span>
lista.forEach(s -&gt; 
    System.out.println(s)
);

<span class="cm">// O con referencia a método</span>
lista.forEach(System.out::println);</pre>
        </div>
      </div>
    </div>
  </div>

  <div id="col4" class="inner-section">
    <div class="card">
      <div class="card-title">Tipos principales — List, Set, Queue</div>
      <table class="stbl">
        <thead><tr><th>Tipo</th><th>Características</th><th>Implementaciones</th></tr></thead>
        <tbody>
          <tr><td>List</td><td>Ordenada por inserción, permite duplicados, acceso por índice</td><td>ArrayList, LinkedList</td></tr>
          <tr><td>Set</td><td>SIN orden definido, NO permite duplicados, rápido para búsqueda</td><td>HashSet, LinkedHashSet, TreeSet</td></tr>
          <tr><td>Queue</td><td>FIFO (primero entra, primero sale), orden de llegada</td><td>LinkedList, PriorityQueue</td></tr>
          <tr><td>Deque</td><td>Doble extremo, se puede acceder/quitar por ambos lados</td><td>LinkedList, ArrayDeque</td></tr>
        </tbody>
      </table>
    </div>
    <div class="card">
      <div class="card-title">ArrayList vs LinkedList</div>
      <div class="grid2">
        <div>
          <span class="badge bp">ArrayList</span>
          <pre><span class="cm">// Array interno redimensionable</span>
<span class="kw">List&lt;String&gt; lista = 
    <span class="kw">new</span> ArrayList&lt;&gt;();

<span class="cm">// ✓ Acceso rápido por índice</span>
<span class="cm">// ✗ Insertar/borrar lento</span>
<span class="cm">// Usar: lectura frecuente</span></pre>
        </div>
        <div>
          <span class="badge bt">LinkedList</span>
          <pre><span class="cm">// Lista enlazada (nodos)</span>
<span class="kw">List&lt;String&gt; lista = 
    <span class="kw">new</span> LinkedList&lt;&gt;();

<span class="cm">// ✗ Acceso lento por índice</span>
<span class="cm">// ✓ Insertar/borrar rápido</span>
<span class="cm">// Usar: colas, pilas</span></pre>
        </div>
      </div>
    </div>
    <div class="card">
      <div class="card-title">Set — evitar duplicados automáticamente</div>
      <pre><span class="cm">// HashSet → rápido, sin orden</span>
Set&lt;String&gt; unicos = <span class="kw">new</span> HashSet&lt;&gt;();
unicos.add(<span class="str">"a"</span>);
unicos.add(<span class="str">"b"</span>);
unicos.add(<span class="str">"a"</span>);  <span class="cm">// No se añade (ya existe)</span>
System.out.println(unicos.size());  <span class="cm">// 2</span>

<span class="cm">// TreeSet → ordenado, más lento pero automáticamente sort</span>
Set&lt;Integer&gt; ordenado = <span class="kw">new</span> TreeSet&lt;&gt;();
ordenado.add(<span class="num">3</span>); ordenado.add(<span class="num">1</span>); ordenado.add(<span class="num">2</span>);
<span class="cm">// Iterar imprime: 1, 2, 3</span></pre>
    </div>
    <div class="card">
      <div class="card-title">Queue — FIFO</div>
      <pre><span class="cm">// Crear cola</span>
Queue&lt;Integer&gt; cola = <span class="kw">new</span> LinkedList&lt;&gt;();

<span class="cm">// Encolar</span>
cola.add(<span class="num">1</span>);     <span class="cm">// o offer()</span>
cola.add(<span class="num">2</span>);

<span class="cm">// Desencolar</span>
<span class="kw">int</span> primero = cola.remove();  <span class="cm">// o poll() → null si vacía</span>
<span class="kw">int</span> frente  = cola.peek();     <span class="cm">// Ver sin quitar</span></pre>
    </div>
  </div>

  <div id="col5" class="inner-section">
    <div class="card">
      <div class="card-title">Map — pares clave-valor</div>
      <span class="badge bb">Tabla de doble entrada</span>
      <pre><span class="cm">// Crear mapa</span>
Map&lt;String, Integer&gt; edades = <span class="kw">new</span> HashMap&lt;&gt;();

<span class="cm">// Insertar (clave, valor)</span>
edades.put(<span class="str">"Juan"</span>, <span class="num">25</span>);
edades.put(<span class="str">"María"</span>, <span class="num">30</span>);

<span class="cm">// Obtener por clave</span>
<span class="kw">int</span> edad = edades.get(<span class="str">"Juan"</span>);    <span class="cm">// 25</span>
<span class="kw">int</span> desconocido = edades.get(<span class="str">"Bob"</span>);  <span class="cm">// null</span>

<span class="cm">// Comprobar existencia</span>
<span class="kw">if</span> (edades.containsKey(<span class="str">"Juan"</span>)) { ... }

<span class="cm">// Eliminar</span>
edades.remove(<span class="str">"Juan"</span>);

<span class="cm">// Recorrer claves</span>
<span class="kw">for</span> (String nombre : edades.keySet()) {
    System.out.println(nombre + <span class="str">": "</span> + edades.get(nombre));
}

<span class="cm">// Recorrer valores</span>
<span class="kw">for</span> (<span class="kw">int</span> e : edades.values()) {
    System.out.println(e);
}

<span class="cm">// Recorrer pares (Entry)</span>
<span class="kw">for</span> (Map.Entry&lt;String, Integer&gt; entrada : edades.entrySet()) {
    String clave = entrada.getKey();
    <span class="kw">int</span> valor = entrada.getValue();
}</pre>
      <div class="tip">Usa <code>entrySet()</code> para recorrer, es más eficiente que <code>keySet()</code> + <code>get()</code>.</div>
    </div>
    <div class="card">
      <div class="card-title">HashMap vs TreeMap</div>
      <div class="mref">
        <div class="mref-row"><span class="mref-name">HashMap</span><span class="mref-desc">Rápido, sin orden. Usa función hash de las claves.</span></div>
        <div class="mref-row"><span class="mref-name">TreeMap</span><span class="mref-desc">Ordenado alfabéticamente, más lento. Las claves deben ser Comparable.</span></div>
      </div>
    </div>
  </div>

  <div id="col6" class="inner-section">
    <div class="card">
      <div class="card-title">Clase Collections — utilidades estáticas</div>
      <span class="badge ba">Similar a Arrays, pero para colecciones</span>
      <pre><span class="cm">// Ordenar una lista</span>
Collections.sort(lista);                    <span class="cm">// orden natural</span>
Collections.sort(lista, comparador);        <span class="cm">// con comparador</span>
Collections.sort(lista, Collections.reverseOrder()); <span class="cm">// inverso</span>

<span class="cm">// Barajar</span>
Collections.shuffle(lista);

<span class="cm">// Busca binaria (requiere lista ordenada)</span>
<span class="kw">int</span> indice = Collections.binarySearch(lista, elemento);

<span class="cm">// Max / Min</span>
Integer maximo = Collections.max(numeros);
Integer minimo = Collections.min(numeros);

<span class="cm">// Llenar</span>
Collections.fill(lista, <span class="str">"valor"</span>);

<span class="cm">// Contar occurrencias</span>
<span class="kw">int</span> veces = Collections.frequency(lista, elemento);</pre>
    </div>
  </div>

  <div id="col7" class="inner-section">
    <div class="card">
      <div class="card-title">Filtrar una lista → removeIf()</div>
      <pre><span class="cm">// Eliminar todos menores de 18</span>
lista.removeIf(p -&gt; p.getEdad() &lt; <span class="num">18</span>);

<span class="cm">// Eliminar strings vacíos</span>
palabras.removeIf(String::isEmpty);</pre>
    </div>
    <div class="card">
      <div class="card-title">Contar elementos que cumplen condición</div>
      <pre><span class="cm">// Con stream (Java 8+)</span>
<span class="kw">long</span> mayores = empleados.stream()
    .filter(e -&gt; e.getEdad() &gt; <span class="num">30</span>)
    .count();

<span class="cm">// Con iterador clásico</span>
<span class="kw">int</span> contador = <span class="num">0</span>;
<span class="kw">for</span> (Empleado e : empleados) {
    <span class="kw">if</span> (e.getEdad() &gt; <span class="num">30</span>) contador++;
}</pre>
    </div>
    <div class="card">
      <div class="card-title">Buscar un elemento</div>
      <pre><span class="cm">// En Set → contains() es O(1)</span>
<span class="kw">if</span> (conjunto.contains(elemento)) { ... }

<span class="cm">// En List → contains() es O(n), pero cómodo</span>
<span class="kw">if</span> (lista.contains(elemento)) { ... }

<span class="cm">// Buscar con condición</span>
Empleado encontrado = empleados.stream()
    .filter(e -&gt; e.getNombre().equals(<span class="str">"Juan"</span>))
    .findFirst()
    .orElse(<span class="kw">null</span>);</pre>
    </div>
  </div>
</div><!-- /colecciones -->


