  <div id="s1" class="inner-section on">
    <div class="card">
      <div class="card-title">Clases anidadas estáticas</div>
      <span class="badge bp">Efecto estructural: organizar código</span>
      <pre><span class="kw">public class</span> Persona {
    <span class="kw">public static class</span> Direccion {
        String calle;
        <span class="kw">int</span> numero;
    }
}

<span class="cm">// Usar desde fuera:</span>
Persona.Direccion dir = <span class="kw">new</span> Persona.Direccion();</pre>
    </div>
    <div class="card">
      <div class="card-title">Clases internas (NO estáticas)</div>
      <span class="badge bt">Acceden a miembros privados de la clase externa</span>
      <pre><span class="kw">public class</span> Coleccion {
    <span class="kw">private</span> List&lt;Integer&gt; datos = <span class="kw">new</span> ArrayList&lt;&gt;();

    <span class="cm">// Clase interna → accede a datos privado</span>
    <span class="kw">public class</span> IteradorPares <span class="kw">implements</span> Iterator&lt;Integer&gt; {
        <span class="kw">private int</span> pos = <span class="num">0</span>;

        <span class="kw">@Override</span>
        <span class="kw">public boolean</span> hasNext() {
            <span class="cm">// Accede a datos (privado de Coleccion)</span>
            <span class="kw">return</span> pos &lt; datos.size();
        }

        <span class="kw">@Override</span>
        <span class="kw">public</span> Integer next() {
            <span class="cm">// Busca el próximo par</span>
            <span class="kw">while</span> (pos &lt; datos.size() && datos.get(pos) % <span class="num">2</span> != <span class="num">0</span>) {
                pos++;
            }
            <span class="kw">return</span> datos.get(pos++);
        }
    }
}</pre>
    </div>
    <div class="card">
      <div class="card-title">Clases anónimas</div>
      <span class="badge ba">Definir clase inline, una sola vez</span>
      <pre><span class="cm">// En lugar de crear una clase nueva, definirla en el new()</span>
Comparator&lt;Empleado&gt; comp = <span class="kw">new</span> Comparator&lt;Empleado&gt;() {
    <span class="kw">@Override</span>
    <span class="kw">public int</span> compare(Empleado e1, Empleado e2) {
        <span class="kw">return</span> e1.getNombre().compareTo(e2.getNombre());
    }
};
empleados.sort(comp);</pre>
      <div class="tip">Las clases anónimas son engorrosas de escribir. Usa lambdas en su lugar (más abajo).</div>
    </div>
  </div>

  <div id="s2" class="inner-section">
    <div class="card">
      <div class="card-title">Expresiones lambda — sintaxis compacta</div>
      <span class="badge bb">Para interfaces funcionales (un método)</span>
      <pre><span class="cm">// Sintaxis: (parámetros) -> cuerpo</span>

<span class="cm">// Lambda simple</span>
Comparator&lt;Empleado&gt; comp = (e1, e2) -&gt; 
    e1.getNombre().compareTo(e2.getNombre());

<span class="cm">// Con bloque {}</span>
Comparator&lt;Empleado&gt; comp2 = (e1, e2) -&gt; {
    String n1 = e1.getNombre().trim().toUpperCase();
    String n2 = e2.getNombre().trim().toUpperCase();
    <span class="kw">return</span> n1.compareTo(n2);
};

<span class="cm">// Sin parámetros</span>
Runnable run = () -&gt; System.out.println(<span class="str">"Hola"</span>);

<span class="cm">// Un parámetro (sin paréntesis)</span>
Consumer&lt;String&gt; print = s -&gt; System.out.println(s);

<span class="cm">// Referencia a método</span>
lista.forEach(System.out::println);  <span class="cm">// método estático o de instancia</span></pre>
      <div class="tip">El compilador deduce tipos de los parámetros y el retorno. Sin parentesis si es un parámetro sin tipo.</tip>
    </div>
    <div class="card">
      <div class="card-title">Interfaces funcionales comunes</div>
      <table class="stbl">
        <thead><tr><th>Interfaz</th><th>Método</th><th>Uso</th></tr></thead>
        <tbody>
          <tr><td>Predicate&lt;T&gt;</td><td>boolean test(T)</td><td>Comprobar condición → filter()</td></tr>
          <tr><td>Consumer&lt;T&gt;</td><td>void accept(T)</td><td>Procesar elemento → forEach()</td></tr>
          <tr><td>Function&lt;T,R&gt;</td><td>R apply(T)</td><td>Transformar elemento → map()</td></tr>
          <tr><td>Supplier&lt;T&gt;</td><td>T get()</td><td>Generar valor (sin parámetros)</td></tr>
          <tr><td>Comparator&lt;T&gt;</td><td>int compare(T,T)</td><td>Ordenar elementos</td></tr>
        </tbody>
      </table>
    </div>
  </div>

  <div id="s3" class="inner-section">
    <div class="card">
      <div class="card-title">Stream API — procesamiento de datos</div>
      <span class="badge bp">Pipeline de transformaciones</span>
      <pre><span class="cm">// Crear stream</span>
List&lt;Integer&gt; nums = Arrays.asList(<span class="num">1</span>, <span class="num">2</span>, <span class="num">3</span>, <span class="num">4</span>, <span class="num">5</span>);
Stream&lt;Integer&gt; stream = nums.stream();

<span class="cm">// Desde array</span>
<span class="kw">int</span>[] arr = {<span class="num">1</span>, <span class="num">2</span>, <span class="num">3</span>};
IntStream stream2 = Arrays.stream(arr);

<span class="cm">// Crear directamente</span>
Stream&lt;String&gt; stream3 = Stream.of(<span class="str">"a"</span>, <span class="str">"b"</span>, <span class="str">"c"</span>);</pre>
    </div>
    <div class="card">
      <div class="card-title">Pipeline típico</div>
      <pre><span class="cm">// source → intermediate → terminal</span>
<span class="kw">long</span> resultado = lista.stream()           <span class="cm">// source</span>
    .filter(e -&gt; e.getEdad() &gt; <span class="num">30</span>)    <span class="cm">// intermediate</span>
    .map(e -&gt; e.getSalario())              <span class="cm">// intermediate</span>
    .count();                               <span class="cm">// terminal</span></pre>
      <div class="info">Los intermedios (filter, map…) devuelven Stream. Los terminales (count, collect…) devuelven un valor específico.</div>
    </div>
  </div>

  <div id="s4" class="inner-section">
    <div class="card">
      <div class="card-title">Operaciones intermedias principales</div>
      <pre><span class="cm">// filter — mantener elementos que cumplen condición</span>
stream.filter(p -&gt; p.length() &gt; <span class="num">3</span>)

<span class="cm">// map — transformar elementos</span>
stream.map(String::toUpperCase)

<span class="cm">// sorted — ordenar</span>
stream.sorted()
stream.sorted((a, b) -&gt; b.compareTo(a))  <span class="cm">// inverso</span>

<span class="cm">// distinct — eliminar duplicados</span>
stream.distinct()

<span class="cm">// limit — primeros N elementos</span>
stream.limit(<span class="num">5</span>)

<span class="cm">// skip — saltar primeros N</span>
stream.skip(<span class="num">2</span>)</pre>
    </div>
    <div class="card">
      <div class="card-title">Operaciones terminales principales</div>
      <pre><span class="cm">// count — número de elementos</span>
<span class="kw">long</span> n = stream.count();

<span class="cm">// forEach — procesar cada elemento</span>
stream.forEach(System.out::println);

<span class="cm">// collect — recopilar en colección</span>
List&lt;String&gt; lista = stream.collect(Collectors.toList());

<span class="cm">// reduce — combinar todos los elementos</span>
<span class="kw">int</span> suma = stream.reduce(<span class="num">0</span>, (a, b) -&gt; a + b);

<span class="cm">// findFirst — primer elemento</span>
Optional&lt;String&gt; primero = stream.findFirst();

<span class="cm">// anyMatch, allMatch, noneMatch</span>
<span class="kw">boolean</span> hay = stream.anyMatch(s -&gt; s.length() &gt; <span class="num">5</span>);</pre>
    </div>
    <div class="card">
      <div class="card-title">Ejemplo completo</div>
      <pre><span class="cm">// Obtener nombres de empleados > 30 años, en mayúsculas, ordenados</span>
List&lt;String&gt; nombres = empleados.stream()
    .filter(e -&gt; e.getEdad() &gt; <span class="num">30</span>)
    .map(Empleado::getNombre)
    .map(String::toUpperCase)
    .sorted()
    .collect(Collectors.toList());

<span class="cm">// Contar empleados por departamento</span>
Map&lt;String, Long&gt; porDepto = empleados.stream()
    .collect(Collectors.groupingBy(
        Empleado::getDepartamento,
        Collectors.counting()
    ));</pre>
    </div>
  </div>

  <div id="s5" class="inner-section">
    <div class="card">
      <div class="card-title">Collectors — recopilar resultados</div>
      <pre><span class="cm">// toList — convertir a Lista</span>
List&lt;Empleado&gt; lista = stream.collect(Collectors.toList());

<span class="cm">// toSet — convertir a Set (sin duplicados)</span>
Set&lt;String&gt; unicos = stream.collect(Collectors.toSet());

<span class="cm">// toMap — convertir a Map (clave, valor)</span>
Map&lt;Integer, String&gt; mapa = empleados.stream()
    .collect(Collectors.toMap(
        Empleado::getId,      <span class="cm">// clave</span>
        Empleado::getNombre   <span class="cm">// valor</span>
    ));

<span class="cm">// joining — concatenar strings</span>
String resultado = nombres.stream()
    .collect(Collectors.joining(<span class="str">", "</span>));  <span class="cm">// "Juan, María, Pedro"</span>

<span class="cm">// summingInt / averagingDouble</span>
<span class="kw">int</span> totalSalario = empleados.stream()
    .collect(Collectors.summingInt(e -&gt; e.getSalario()));
<span class="kw">double</span> media = empleados.stream()
    .collect(Collectors.averagingDouble(Empleado::getSalario));

<span class="cm">// groupingBy — agrupar por criterio</span>
Map&lt;String, List&lt;Empleado&gt;&gt; grupos = empleados.stream()
    .collect(Collectors.groupingBy(Empleado::getDepartamento));</pre>
    </div>
  </div>

  <div id="s6" class="inner-section">
    <div class="card">
      <div class="card-title">Optional&lt;T&gt; — contenedor de valor o null</div>
      <pre><span class="cm">// findFirst devuelve Optional</span>
Optional&lt;Empleado&gt; primero = empleados.stream()
    .findFirst();

<span class="cm">// Comprobar si tiene valor</span>
<span class="kw">if</span> (primero.isPresent()) {
    Empleado e = primero.get();
}

<span class="cm">// orElse — valor por defecto</span>
Empleado e = primero.orElse(<span class="kw">null</span>);

<span class="cm">// orElseThrow — lanzar excepción si no existe</span>
Empleado e2 = primero.orElseThrow(
    () -&gt; <span class="kw">new</span> RuntimeException(<span class="str">"No encontrado"</span>)
);

<span class="cm">// map — transformar el valor si existe</span>
Optional&lt;String&gt; nombre = primero.map(Empleado::getNombre);

<span class="cm">// filter — filtrar dentro de Optional</span>
Optional&lt;Empleado&gt; mayores30 = primero
    .filter(e -&gt; e.getEdad() &gt; <span class="num">30</span>);</pre>
    </div>
  </div>
</div><!-- /streams -->


<!-- ══════════════════════════════════════════════
     TOPIC: SIMULACRO
══════════════════════════════════════════════ -->
<div id="simulacro" class="topic-section">
  <div class="inner-nav">
    <button class="inner-btn on" onclick="showInner('simulacro','sim1',this)">Sopa de letras</button>
    <button class="inner-btn"   onclick="showInner('simulacro','sim2',this)">Diagrama clases</button>
    <button class="inner-btn"   onclick="showInner('simulacro','sim3',this)">Consultas</button>
  </div>

  <div id="sim1" class="inner-section on">
    <div class="card">
      <div class="card-title">Ejercicio: Buscar palabras en Sopa de Letras</div>
      <p style="font-size: 12.5px; color: var(--text2); margin-bottom: 12px;">
        Dada una sopa de letras (char[][] sopaDeLetras) y un diccionario (List&lt;String&gt; diccionario), buscar cada palabra 
        en cuatro direcciones: horizontal derecha, horizontal izquierda, vertical arriba, vertical abajo.
      </p>
      <pre><span class="cm">// Métodos a implementar</span>
<span class="kw">public static int</span>[] buscarHorizontalDerecha(
    <span class="kw">char</span>[][] sopa, String palabra) { ... }

<span class="kw">public static int</span>[] buscarHorizontalIzquierda(
    <span class="kw">char</span>[][] sopa, String palabra) { ... }

<span class="kw">public static int</span>[] buscarVerticalAbajo(
    <span class="kw">char</span>[][] sopa, String palabra) { ... }

<span class="kw">public static int</span>[] buscarVerticalArriba(
    <span class="kw">char</span>[][] sopa, String palabra) { ... }

<span class="cm">// Método principal</span>
<span class="kw">public static void</span> buscar(
    <span class="kw">char</span>[][] sopa, List&lt;String&gt; diccionario) {
    <span class="kw">for</span> (String palabra : diccionario) {
        <span class="kw">int</span>[] posH_der = buscarHorizontalDerecha(sopa, palabra);
        <span class="kw">int</span>[] posH_izq = buscarHorizontalIzquierda(sopa, palabra);
        <span class="kw">int</span>[] posV_aba = buscarVerticalAbajo(sopa, palabra);
        <span class="kw">int</span>[] posV_arr = buscarVerticalArriba(sopa, palabra);

        <span class="cm">// Mostrar resultados</span>
        <span class="kw">if</span> (posH_der != <span class="kw">null</span>)
            System.out.println(palabra + <span class="str">" derecha: "</span> + 
                Arrays.toString(posH_der));
        <span class="cm">// ... igual para otros</span>
    }
}</pre>
    </div>
    <div class="card">
      <div class="card-title">Pistas de implementación</div>
      <ul class="dots">
        <li><strong>Horizontal derecha:</strong> Recorrer cada fila, buscar palabra de izquierda a derecha</li>
        <li><strong>Horizontal izquierda:</strong> Recorrer cada fila, buscar palabra invertida</li>
        <li><strong>Vertical abajo:</strong> Recorrer cada columna, buscar palabra de arriba a abajo</li>
        <li><strong>Vertical arriba:</strong> Recorrer cada columna, buscar palabra invertida</li>
        <li>Devolver null si no se encuentra</li>
        <li>Devolver [fila, columna] del inicio de la palabra si la encuentra</li>
      </ul>
    </div>
  </div>

  <div id="sim2" class="inner-section">
    <div class="card">
      <div class="card-title">Diagrama UML — Persona, Empleado, Empresa, Contrato</div>
      <p style="font-size: 12.5px; color: var(--text2); margin-bottom: 12px;">
        Implementar las siguientes clases según el diagrama:
      </p>
      <div class="mref">
        <div class="mref-row"><span class="mref-name">Persona (abstract)</span><span class="mref-desc">dni, nombre, apellidos, fechaNacimiento. Comparable por apellidos+nombre.</span></div>
        <div class="mref-row"><span class="mref-name">Empleado extends Persona</span><span class="mref-desc">Añade especialidad. equals() por dni. toString() incluye especialidad.</span></div>
        <div class="mref-row"><span class="mref-name">Empresa</span><span class="mref-desc">nombre, tipoNegocio. equals() por nombre. Lista de Contratos.</span></div>
        <div class="mref-row"><span class="mref-name">Contrato</span><span class="mref-desc">trabajador, empresa, fechaAlta, fechaBaja (null si activo), salario.</span></div>
      </div>
      <pre style="margin-top: 12px;"><span class="cm">// Ejemplo de equals() en Persona</span>
<span class="kw">@Override</span>
<span class="kw">public boolean</span> equals(Object obj) {
    <span class="kw">if</span> (!(obj <span class="kw">instanceof</span> Persona)) <span class="kw">return false</span>;
    <span class="kw">return</span> <span class="kw">this</span>.dni.equals(((Persona) obj).dni);
}

<span class="cm">// Ejemplo de compareTo (por apellidos + nombre)</span>
<span class="kw">@Override</span>
<span class="kw">public int</span> compareTo(Persona otra) {
    <span class="kw">int</span> apellidosCmp = <span class="kw">this</span>.apellidos
        .compareTo(otra.apellidos);
    <span class="kw">if</span> (apellidosCmp != <span class="num">0</span>) <span class="kw">return</span> apellidosCmp;
    <span class="kw">return this</span>.nombre.compareTo(otra.nombre);
}</pre>
    </div>
    <div class="card">
      <div class="card-title">toString() de Contrato</div>
      <pre><span class="cm">// Formato: "Trabajador (dni) - Empresa - Salario - Fecha inicio - Fecha fin"</span>
<span class="cm">// Si fechaBaja es null → mostrar solo fecha inicio</span>
<span class="cm">// Ejemplo: "Juan García (12345678A) - TechCorp - 2000€ - 10/12/2005 - 30/06/2007"</span>
<span class="cm">//         "María López (98765432B) - TechCorp - 1800€ - 15/03/2015 - "</span>

<span class="kw">@Override</span>
<span class="kw">public</span> String toString() {
    DateTimeFormatter fmt = DateTimeFormatter.ofPattern(<span class="str">"dd/MM/yyyy"</span>);
    String fin = (fechaBaja == <span class="kw">null</span>) ? <span class="str">"en activo"</span> 
                                        : fechaBaja.format(fmt);
    <span class="kw">return</span> trabajador.getNombre() + <span class="str">" - "</span> 
         + empresa.getNombre() + <span class="str">" - "</span>
         + salario + <span class="str">"€ - "</span>
         + fechaAlta.format(fmt) + <span class="str">" - "</span> + fin;
}</pre>
    </div>
  </div>

  <div id="sim3" class="inner-section">
    <div class="card">
      <div class="card-title">Consultas a implementar (con Streams)</div>
      <pre><span class="cm">// 1. Número de empleados con más de 1 contrato extinguido</span>
<span class="kw">long</span> empleadosConMasDeUnExtinguido = empleados.stream()
    .filter(e -&gt; e.getContratos().stream()
        .filter(c -&gt; c.getFechaBaja() != <span class="kw">null</span>)
        .count() &gt; <span class="num">1</span>)
    .count();

<span class="cm">// 2. Trabajador con mayor salario en una fecha dada</span>
LocalDate fecha = LocalDate.of(<span class="num">2020</span>, <span class="num">6</span>, <span class="num">15</span>);
Empleado mejorPagado = empleados.stream()
    .flatMap(e -&gt; e.getContratos().stream()
        .filter(c -&gt; esActivoEnFecha(c, fecha))
        .map(c -&gt; new AbstractMap.SimpleEntry&lt;&gt;(e, c)))
    .max(Comparator.comparingDouble(
        e -&gt; e.getValue().getSalario()))
    .map(AbstractMap.SimpleEntry::getKey)
    .orElse(<span class="kw">null</span>);

<span class="cm">// 3. Listado de empleados en empresa X en fecha Y</span>
Empresa empresa = empresas.get(<span class="num">0</span>);
LocalDate fecha = LocalDate.of(<span class="num">2022</span>, <span class="num">3</span>, <span class="num">15</span>);
List&lt;Empleado&gt; trabajandoEnEsa = empleados.stream()
    .filter(e -&gt; e.getContratos().stream()
        .anyMatch(c -&gt; c.getEmpresa().equals(empresa) 
                    && esActivoEnFecha(c, fecha)))
    .sorted()
    .collect(Collectors.toList());

<span class="cm">// 4. Suma de salarios en empresa X en fecha Y</span>
<span class="kw">double</span> totalSalarios = empleados.stream()
    .flatMap(e -&gt; e.getContratos().stream()
        .filter(c -&gt; c.getEmpresa().equals(empresa)
                   && esActivoEnFecha(c, fecha))
        .map(c -&gt; c.getSalario()))
    .mapToDouble(Double::doubleValue)
    .sum();

<span class="cm">// 5. Empleado más viejo en empresa X en fecha Y</span>
Empleado masViejo = empleados.stream()
    .filter(e -&gt; e.getContratos().stream()
        .anyMatch(c -&gt; c.getEmpresa().equals(empresa)
                    && esActivoEnFecha(c, fecha)))
    .min(Comparator.comparing(Persona::getFechaNacimiento))
    .orElse(<span class="kw">null</span>);

<span class="cm">// Método auxiliar</span>
<span class="kw">private static boolean</span> esActivoEnFecha(Contrato c, LocalDate fecha) {
    <span class="kw">return</span> !fecha.isBefore(c.getFechaAlta()) &&
           (c.getFechaBaja() == <span class="kw">null</span> || fecha.isBefore(c.getFechaBaja()));
}</pre>
    </div>
    <div class="card">
      <div class="card-title">Datos de prueba</div>
      <pre><span class="cm">// 2 empresas</span>
Empresa google = <span class="kw">new</span> Empresa(<span class="str">"Google"</span>, <span class="str">"Tecnología"</span>);
Empresa amazon = <span class="kw">new</span> Empresa(<span class="str">"Amazon"</span>, <span class="str">"E-commerce"</span>);

<span class="cm">// 4 empleados</span>
Empleado juan = <span class="kw">new</span> Empleado(
    <span class="str">"12345678A"</span>, <span class="str">"Juan"</span>, <span class="str">"García"</span>,
    LocalDate.of(<span class="num">1990</span>, <span class="num">3</span>, <span class="num">15</span>), <span class="str">"Backend"</span>);

Empleado maria = <span class="kw">new</span> Empleado(
    <span class="str">"98765432B"</span>, <span class="str">"María"</span>, <span class="str">"López"</span>,
    LocalDate.of(<span class="num">1992</span>, <span class="num">7</span>, <span class="num">22</span>), <span class="str">"Frontend"</span>);

<span class="cm">// ... más empleados</span>

<span class="cm">// Contratos variados</span>
google.agregarContrato(<span class="kw">new</span> Contrato(
    juan, google,
    LocalDate.of(<span class="num">2018</span>, <span class="num">1</span>, <span class="num">15</span>),
    LocalDate.of(<span class="num">2021</span>, <span class="num">6</span>, <span class="num">30</span>),  <span class="cm">// extinguido</span>
    <span class="num">2500</span>
));</pre>
    </div>
  </div>
</div><!-- /simulacro -->

<script>
function showTopic(id, btn) {
  document.querySelectorAll('.topic-section').forEach(s => s.classList.remove('on'));
  document.querySelectorAll('.topic-btn').forEach(b => b.classList.remove('on'));
  document.getElementById(id).classList.add('on');
  btn.classList.add('on');
}

function showInner(topic, id, btn) {
  const parent = document.getElementById(topic);
  parent.querySelectorAll('.inner-section').forEach(s => s.classList.remove('on'));
  parent.querySelectorAll('.inner-btn').forEach(b => b.classList.remove('on'));
  document.getElementById(id).classList.add('on');
  btn.classList.add('on');
}
</script>
