    --bg: #0f0f13;
    --bg2: #16161d;
    --bg3: #1e1e28;
    --bg4: #25252f;
    --border: #2e2e3a;
    --border2: #3a3a4a;
    --text: #e8e6f0;
    --text2: #9896a8;
    --text3: #5f5d70;
    --purple: #a78bfa;
    --purple-bg: #1e1a35;
    --purple-border: #4c3d8a;
    --teal: #34d399;
    --teal-bg: #0d2620;
    --teal-border: #1a5c48;
    --amber: #fbbf24;
    --amber-bg: #1f1a0a;
    --amber-border: #5c4a0a;
    --coral: #f87171;
    --coral-bg: #1f0f0f;
    --coral-border: #5c2020;
    --blue: #60a5fa;
    --blue-bg: #0d1a2e;
    --blue-border: #1a3a5c;
    --kw: #c084fc;
    --cm: #4a4860;
    --str: #34d399;
    --num: #f87171;
    --fn: #60a5fa;
  }

  * { box-sizing: border-box; margin: 0; padding: 0; }

  body {
    background: var(--bg);
    color: var(--text);
    font-family: 'Segoe UI', system-ui, sans-serif;
    font-size: 14px;
    line-height: 1.6;
  }

  header {
    background: var(--bg2);
    border-bottom: 1px solid var(--border);
    padding: 16px 24px;
    display: flex;
    align-items: center;
    gap: 16px;
    position: sticky;
    top: 0;
    z-index: 100;
  }
  header h1 { font-size: 16px; font-weight: 600; color: var(--text); letter-spacing: .02em; }
  header .chip {
    background: var(--purple-bg);
    border: 1px solid var(--purple-border);
    color: var(--purple);
    font-size: 11px;
    padding: 2px 8px;
    border-radius: 20px;
    font-weight: 500;
  }

  .topic-nav {
    background: var(--bg2);
    border-bottom: 1px solid var(--border);
    padding: 0 24px;
    display: flex;
    gap: 0;
    overflow-x: auto;
  }
  .topic-btn {
    background: none;
    border: none;
    border-bottom: 2px solid transparent;
    color: var(--text2);
    font-size: 13px;
    font-weight: 500;
    padding: 12px 18px;
    cursor: pointer;
    transition: all .15s;
