<!-- ══════════════════════════════════════════════
     TOPIC: COLECCIONES
══════════════════════════════════════════════ -->
<div id="colecciones" class="topic-section on">
  <div class="inner-nav">
    <button class="inner-btn on" onclick="showInner('colecciones','col1',this)">List</button>
    <button class="inner-btn" onclick="showInner('colecciones','col2',this)">Set</button>
    <button class="inner-btn" onclick="showInner('colecciones','col3',this)">Map</button>
    <button class="inner-btn" onclick="showInner('colecciones','col4',this)">Iteradores</button>
    <button class="inner-btn" onclick="showInner('colecciones','col5',this)">Generics</button>
    <button class="inner-btn" onclick="showInner('colecciones','col6',this)">Collections</button>
  </div>

  <div id="col1" class="inner-section on">
    <div class="card">
      <div class="card-title">List — Colección ordenada con duplicados</div>
      <pre><span class="kw">import</span> java.util.*;

<span class="cm">// ArrayList — dinámico, acceso rápido por índice</span>
List&lt;String&gt; lista = <span class="kw">new</span> ArrayList&lt;&gt;();
lista.add(<span class="str">"Juan"</span>);
lista.add(<span class="str">"María"</span>);
lista.add(<span class="num">0</span>, <span class="str">"Ana"</span>);           <span class="cm">// insertar en posición</span>
System.out.println(lista.get(<span class="num">0</span>));     <span class="cm">// Ana</span>
lista.remove(<span class="num">1</span>);                <span class="cm">// quitar por índice</span>
lista.remove(<span class="str">"Juan"</span>);           <span class="cm">// quitar por valor</span>
System.out.println(lista.size());       <span class="cm">// 2</span>
<span class="kw">boolean</span> existe = lista.contains(<span class="str">"María"</span>);

<span class="cm">// LinkedList — mejor para insertar/quitar al principio</span>
List&lt;Integer&gt; enlazada = <span class="kw">new</span> LinkedList&lt;&gt;();
enlazada.add(<span class="num">1</span>);
enlazada.add(<span class="num">2</span>);
enlazada.addFirst(<span class="num">0</span>);     <span class="cm">// LinkedList específico</span>
enlazada.removeLast();       <span class="cm">// LinkedList específico</span></pre>
      <div class="tip">ArrayList es más rápido para leer. LinkedList es más rápido para insertar/quitar al inicio.</div>
    </div>

    <div class="card">
      <div class="card-title">Métodos clave de List</div>
      <div class="mref">
        <div class="mref-row"><span class="mref-name">add(elemento)</span><span class="mref-desc">Añadir al final. Devuelve boolean</span></div>
        <div class="mref-row"><span class="mref-name">add(índice, elemento)</span><span class="mref-desc">Insertar en posición. Desplaza el resto</span></div>
        <div class="mref-row"><span class="mref-name">get(índice)</span><span class="mref-desc">Obtener elemento en posición</span></div>
        <div class="mref-row"><span class="mref-name">remove(índice)</span><span class="mref-desc">Quitar por índice</span></div>
        <div class="mref-row"><span class="mref-name">remove(elemento)</span><span class="mref-desc">Quitar primera ocurrencia del elemento</span></div>
        <div class="mref-row"><span class="mref-name">indexOf(elemento)</span><span class="mref-desc">Posición del elemento (-1 si no existe)</span></div>
        <div class="mref-row"><span class="mref-name">contains(elemento)</span><span class="mref-desc">¿Contiene el elemento?</span></div>
        <div class="mref-row"><span class="mref-name">size()</span><span class="mref-desc">Número de elementos. Devuelve int</span></div>
        <div class="mref-row"><span class="mref-name">isEmpty()</span><span class="mref-desc">¿Está vacía?</span></div>
        <div class="mref-row"><span class="mref-name">clear()</span><span class="mref-desc">Elimina todos los elementos</span></div>
      </div>
    </div>

    <div class="card">
      <div class="card-title">Recorrer una List</div>
      <pre><span class="cm">// 1. For tradicional — con índice</span>
<span class="kw">for</span> (<span class="kw">int</span> i = <span class="num">0</span>; i &lt; lista.size(); i++) {
    System.out.println(lista.get(i));
}

<span class="cm">// 2. For-each — más limpio</span>
<span class="kw">for</span> (String nombre : lista) {
    System.out.println(nombre);
}

<span class="cm">// 3. Iterador explícito</span>
Iterator&lt;String&gt; it = lista.iterator();
<span class="kw">while</span> (it.hasNext()) {
    System.out.println(it.next());
}

<span class="cm">// 4. forEach con lambda (Java 8+)</span>
lista.forEach(nombre -&gt; System.out.println(nombre));</pre>
    </div>
  </div>

  <div id="col2" class="inner-section">
    <div class="card">
      <div class="card-title">Set — Sin orden, sin duplicados</div>
      <pre><span class="cm">// HashSet — orden indeterminado, rápido</span>
Set&lt;String&gt; conjunto = <span class="kw">new</span> HashSet&lt;&gt;();
conjunto.add(<span class="str">"A"</span>);
conjunto.add(<span class="str">"B"</span>);
conjunto.add(<span class="str">"A"</span>);    <span class="cm">// no añade (es duplicado)</span>
System.out.println(conjunto.size());  <span class="cm">// 2</span>

<span class="cm">// TreeSet — ordenado, más lento que HashSet</span>
Set&lt;Integer&gt; ordenado = <span class="kw">new</span> TreeSet&lt;&gt;();
ordenado.add(<span class="num">3</span>);
ordenado.add(<span class="num">1</span>);
ordenado.add(<span class="num">2</span>);
<span class="cm">// iterando: 1, 2, 3 (orden natural)</span>

<span class="cm">// LinkedHashSet — orden de inserción, sin duplicados</span>
Set&lt;String&gt; con_orden = <span class="kw">new</span> LinkedHashSet&lt;&gt;();</pre>
      <div class="tip">TreeSet requiere que los elementos sean Comparable o pasar un Comparator.</div>
    </div>

    <div class="card">
      <div class="card-title">Métodos clave de Set</div>
      <div class="mref">
        <div class="mref-row"><span class="mref-name">add(elemento)</span><span class="mref-desc">Añadir. Devuelve false si ya existía</span></div>
        <div class="mref-row"><span class="mref-name">remove(elemento)</span><span class="mref-desc">Quitar un elemento</span></div>
        <div class="mref-row"><span class="mref-name">contains(elemento)</span><span class="mref-desc">¿Contiene?</span></div>
        <div class="mref-row"><span class="mref-name">size()</span><span class="mref-desc">Número de elementos</span></div>
        <div class="mref-row"><span class="mref-name">isEmpty()</span><span class="mref-desc">¿Vacío?</span></div>
        <div class="mref-row"><span class="mref-name">iterator()</span><span class="mref-desc">Obtener iterador</span></div>
      </div>
    </div>
  </div>

  <div id="col3" class="inner-section">
    <div class="card">
      <div class="card-title">Map — Pares clave-valor</div>
      <pre><span class="cm">// HashMap — clave única, valor any</span>
Map&lt;String, Integer&gt; mapa = <span class="kw">new</span> HashMap&lt;&gt;();
mapa.put(<span class="str">"Juan"</span>, <span class="num">25</span>);
mapa.put(<span class="str">"María"</span>, <span class="num">30</span>);
System.out.println(mapa.get(<span class="str">"Juan"</span>));        <span class="cm">// 25</span>
System.out.println(mapa.getOrDefault(<span class="str">"Ana"</span>, <span class="num">0</span>)); <span class="cm">// 0 (no existe)</span>
mapa.remove(<span class="str">"Juan"</span>);

<span class="cm">// TreeMap — ordenado por clave, más lento</span>
Map&lt;String, Double&gt; ordenado = <span class="kw">new</span> TreeMap&lt;&gt;();
ordenado.put(<span class="str">"C"</span>, <span class="num">3.0</span>);
ordenado.put(<span class="str">"A"</span>, <span class="num">1.0</span>);
<span class="cm">// iterando: A→1.0, C→3.0 (orden alfabético)</span></pre>
    </div>

    <div class="card">
      <div class="card-title">Recorrer un Map</div>
      <pre><span class="cm">// 1. Recorrer claves</span>
<span class="kw">for</span> (String clave : mapa.keySet()) {
    System.out.println(clave + <span class="str">" → "</span> + mapa.get(clave));
}

<span class="cm">// 2. Recorrer valores</span>
<span class="kw">for</span> (Integer valor : mapa.values()) {
    System.out.println(valor);
}

<span class="cm">// 3. Recorrer entradas (más eficiente)</span>
<span class="kw">for</span> (Map.Entry&lt;String, Integer&gt; entrada : mapa.entrySet()) {
    System.out.println(entrada.getKey() + <span class="str">" → "</span> + entrada.getValue());
}

<span class="cm">// 4. forEach con lambda</span>
mapa.forEach((clave, valor) -&gt; System.out.println(clave + <span class="str">" → "</span> + valor));</pre>
    </div>
  </div>

  <div id="col4" class="inner-section">
    <div class="card">
      <div class="card-title">Iterator — Recorrer colecciones</div>
      <pre>Iterator&lt;String&gt; it = lista.iterator();
<span class="kw">while</span> (it.hasNext()) {
    String elemento = it.next();
    System.out.println(elemento);
    <span class="cm">// it.remove();  // quitar elemento actual</span>
}

<span class="cm">// Patrón: comprobar antes de llamar a next()</span>
<span class="kw">if</span> (it.hasNext()) {
    String primero = it.next();
}</pre>
      <div class="warn">Solo puedes llamar a <code>next()</code> UNA VEZ por iteración del while. Llamarlo dos veces avanza dos posiciones.</div>
    </div>
  </div>

  <div id="col5" class="inner-section">
    <div class="card">
      <div class="card-title">Genéricos — Tipos con restricción</div>
      <pre><span class="cm">// SIN genéricos (antiguo, no recomendado)</span>
List lista = <span class="kw">new</span> ArrayList();  <span class="cm">// acepta cualquier tipo</span>
lista.add(<span class="str">"Texto"</span>);
lista.add(<span class="num">42</span>);
String s = (String) lista.get(<span class="num">0</span>);  <span class="cm">// cast obligatorio</span>

<span class="cm">// CON genéricos (Java 5+, recomendado)</span>
List&lt;String&gt; lista2 = <span class="kw">new</span> ArrayList&lt;&gt;();  <span class="cm">// solo String</span>
lista2.add(<span class="str">"Texto"</span>);
<span class="cm">// lista2.add(42);  // error de compilación</span>
String s2 = lista2.get(<span class="num">0</span>);  <span class="cm">// sin cast</span>

<span class="cm">// Tipos genéricos en métodos</span>
<span class="kw">public static</span> &lt;T&gt; <span class="kw">void</span> imprimir(List&lt;T&gt; lista) {
    <span class="kw">for</span> (T elemento : lista) {
        System.out.println(elemento);
    }
}</pre>
      <div class="tip">Los genéricos son solo para compilación. En runtime, todos son Object (type erasure).</div>
    </div>
  </div>

  <div id="col6" class="inner-section">
    <div class="card">
      <div class="card-title">Clase Collections — Métodos estáticos útiles</div>
      <div class="mref">
        <div class="mref-row"><span class="mref-name">Collections.sort(lista)</span><span class="mref-desc">Ordena una List (implementa Comparable)</span></div>
        <div class="mref-row"><span class="mref-name">Collections.sort(lista, comparador)</span><span class="mref-desc">Ordena con Comparator personalizado</span></div>
        <div class="mref-row"><span class="mref-name">Collections.shuffle(lista)</span><span class="mref-desc">Mezcla los elementos aleatoriamente</span></div>
        <div class="mref-row"><span class="mref-name">Collections.reverse(lista)</span><span class="mref-desc">Invierte el orden</span></div>
        <div class="mref-row"><span class="mref-name">Collections.binarySearch(lista, elem)</span><span class="mref-desc">Busca en lista ordenada</span></div>
        <div class="mref-row"><span class="mref-name">Collections.max(coleccion)</span><span class="mref-desc">Elemento máximo</span></div>
        <div class="mref-row"><span class="mref-name">Collections.min(coleccion)</span><span class="mref-desc">Elemento mínimo</span></div>
        <div class="mref-row"><span class="mref-name">Collections.frequency(coleccion, elem)</span><span class="mref-desc">Cuenta ocurrencias</span></div>
      </div>
      <pre style="margin-top:10px"><span class="kw">import</span> java.util.Collections;

List&lt;Integer&gt; numeros = <span class="kw">new</span> ArrayList&lt;&gt;(Arrays.asList(<span class="num">3</span>, <span class="num">1</span>, <span class="num">4</span>, <span class="num">1</span>, <span class="num">5</span>));
Collections.sort(numeros);           <span class="cm">// [1, 1, 3, 4, 5]</span>
System.out.println(Collections.max(numeros));  <span class="cm">// 5</span>
System.out.println(Collections.frequency(numeros, <span class="num">1</span>)); <span class="cm">// 2</span></pre>
    </div>
  </div>
</div>

<!-- ══════════════════════════════════════════════
     TOPIC: FECHAS Y HORAS
══════════════════════════════════════════════ -->
<div id="fechas" class="topic-section">
  <div class="inner-nav">
    <button class="inner-btn on" onclick="showInner('fechas','f1',this)">LocalDate</button>
    <button class="inner-btn" onclick="showInner('fechas','f2',this)">LocalTime</button>
    <button class="inner-btn" onclick="showInner('fechas','f3',this)">LocalDateTime</button>
    <button class="inner-btn" onclick="showInner('fechas','f4',this)">Period / Duration</button>
    <button class="inner-btn" onclick="showInner('fechas','f5',this)">Formato</button>
    <button class="inner-btn" onclick="showInner('fechas','f6',this)">Errores comunes</button>
  </div>

  <div id="f1" class="inner-section on">
    <div class="card">
      <div class="card-title">LocalDate — Solo fecha</div>
      <pre><span class="kw">import</span> java.time.*;

<span class="cm">// Crear LocalDate</span>
LocalDate hoy = LocalDate.now();
LocalDate fecha = LocalDate.of(<span class="num">2005</span>, <span class="num">12</span>, <span class="num">25</span>);  <span class="cm">// 25/12/2005</span>
LocalDate parsed = LocalDate.parse(<span class="str">"2005-12-25"</span>);   <span class="cm">// formato ISO</span>

<span class="cm">// Métodos de consulta</span>
<span class="kw">int</span> year = fecha.getYear();           <span class="cm">// 2005</span>
<span class="kw">int</span> mes = fecha.getMonthValue();      <span class="cm">// 12 (1-12)</span>
<span class="kw">int</span> dia = fecha.getDayOfMonth();      <span class="cm">// 25</span>
Month mes2 = fecha.getMonth();         <span class="cm">// DECEMBER (enum)</span>
DayOfWeek dia_semana = fecha.getDayOfWeek();  <span class="cm">// SUNDAY</span>

<span class="cm">// Operaciones (inmutables, devuelven new LocalDate)</span>
LocalDate manana = hoy.plusDays(<span class="num">1</span>);
LocalDate el_año_que_viene = fecha.plusYears(<span class="num">1</span>);
LocalDate hace_un_mes = hoy.minusMonths(<span class="num">1</span>);
LocalDate con_otro_dia = fecha.withDayOfMonth(<span class="num">1</span>);  <span class="cm">// primer día del mes</span>

<span class="cm">// Comparaciones</span>
<span class="kw">if</span> (hoy.isBefore(el_año_que_viene)) { ... }
<span class="kw">if</span> (hoy.isAfter(fecha)) { ... }
<span class="kw">if</span> (hoy.isEqual(fecha)) { ... }</span></pre>
      <div class="tip">LocalDate es inmutable. Todos los métodos devuelven un nuevo objeto, no modifican el original.</div>
    </div>
  </div>

  <div id="f2" class="inner-section">
    <div class="card">
      <div class="card-title">LocalTime — Solo hora</div>
      <pre><span class="cm">// Crear LocalTime</span>
LocalTime ahora = LocalTime.now();
LocalTime entrada = LocalTime.of(<span class="num">8</span>, <span class="num">30</span>);     <span class="cm">// 08:30:00</span>
LocalTime preciso = LocalTime.of(<span class="num">14</span>, <span class="num">45</span>, <span class="num">30</span>);  <span class="cm">// 14:45:30</span>

<span class="cm">// Métodos de consulta</span>
<span class="kw">int</span> hora = entrada.getHour();        <span class="cm">// 8</span>
<span class="kw">int</span> minuto = entrada.getMinute();    <span class="cm">// 30</span>
<span class="kw">int</span> segundo = entrada.getSecond();  <span class="cm">// 0</span>

<span class="cm">// Operaciones</span>
LocalTime salida = entrada.plusHours(<span class="num">6</span>);
LocalTime sin_segundos = ahora.withSecond(<span class="num">0</span>);

<span class="cm">// Comparaciones</span>
<span class="kw">if</span> (ahora.isAfter(entrada) && ahora.isBefore(LocalTime.of(<span class="num">17</span>, <span class="num">0</span>))) {
    System.out.println(<span class="str">"Estamos en horario de clase"</span>);
}</pre>
    </div>
  </div>

  <div id="f3" class="inner-section">
    <div class="card">
      <div class="card-title">LocalDateTime — Fecha y hora juntas</div>
      <pre><span class="cm">// Crear LocalDateTime</span>
LocalDateTime ahora = LocalDateTime.now();
LocalDateTime evento = LocalDateTime.of(<span class="num">2024</span>, <span class="num">5</span>, <span class="num">11</span>, <span class="num">14</span>, <span class="num">30</span>);
LocalDateTime parsed = LocalDateTime.parse(<span class="str">"2024-05-11T14:30:00"</span>);

<span class="cm">// Acceder a fecha u hora por separado</span>
LocalDate solo_fecha = evento.toLocalDate();
LocalTime solo_hora = evento.toLocalTime();

<span class="cm">// Operaciones</span>
LocalDateTime luego = ahora.plusDays(<span class="num">1</span>).plusHours(<span class="num">3</span>);
LocalDateTime actualizado = evento.withYear(<span class="num">2025</span>);</pre>
    </div>
  </div>

  <div id="f4" class="inner-section">
    <div class="card">
      <div class="card-title">Period — Diferencia entre fechas</div>
      <pre><span class="cm">// Calcular período entre dos fechas</span>
LocalDate inicio = LocalDate.of(<span class="num">2005</span>, <span class="num">12</span>, <span class="num">10</span>);
LocalDate fin = LocalDate.now();
Period periodo = inicio.until(fin);  <span class="cm">// o fin.minusYears(...)</span>

<span class="kw">int</span> años = periodo.getYears();
<span class="kw">int</span> meses = periodo.getMonths();
<span class="kw">int</span> dias = periodo.getDays();

System.out.println(String.format(<span class="str">"%d años, %d meses y %d días"</span>, años, meses, dias));</pre>
      <div class="tip">Period es para diferencias entre fechas (días, meses, años). Duration es para diferencias entre horas (horas, minutos, segundos).</div>
    </div>

    <div class="card">
      <div class="card-title">Duration — Diferencia entre horas</div>
      <pre><span class="cm">// Calcular duración entre dos horas/momentos</span>
LocalTime inicio_clase = LocalTime.of(<span class="num">8</span>, <span class="num">30</span>);
LocalTime fin_clase = LocalTime.of(<span class="num">10</span>, <span class="num">15</span>);
Duration duracion = Duration.between(inicio_clase, fin_clase);

<span class="kw">long</span> minutos = duracion.toMinutes();    <span class="cm">// 105</span>
<span class="kw">long</span> segundos = duracion.getSeconds(); <span class="cm">// 6300</span></pre>
    </div>
  </div>

  <div id="f5" class="inner-section">
    <div class="card">
      <div class="card-title">DateTimeFormatter — Formatear y parsear fechas</div>
      <pre><span class="kw">import</span> java.time.format.*;

<span class="cm">// Formatos predefinidos</span>
LocalDate hoy = LocalDate.now();
System.out.println(hoy.format(DateTimeFormatter.ISO_DATE));  <span class="cm">// 2026-05-13</span>

<span class="cm">// Formato personalizado</span>
DateTimeFormatter fmt = DateTimeFormatter.ofPattern(<span class="str">"dd/MM/yyyy"</span>);
System.out.println(hoy.format(fmt));  <span class="cm">// 13/05/2026</span>

DateTimeFormatter fmt2 = DateTimeFormatter.ofPattern(<span class="str">"EEEE, d MMMM yyyy"</span>, Locale.getDefault());
System.out.println(hoy.format(fmt2));  <span class="cm">// miércoles, 13 mayo 2026 (locale español)</span>

<span class="cm">// Parsear texto a fecha</span>
String texto = <span class="str">"13/05/2026"</span>;
<span class="kw">try</span> {
    LocalDate fecha = LocalDate.parse(texto, DateTimeFormatter.ofPattern(<span class="str">"dd/MM/yyyy"</span>));
    System.out.println(fecha);
} <span class="kw">catch</span> (DateTimeParseException e) {
    System.out.println(<span class="str">"Formato de fecha incorrecto"</span>);
}</pre>
      <div class="warn">Los patrones de formato son case-sensitive: <code>yyyy</code> (4 dígitos), <code>yy</code> (2 dígitos), <code>MM</code> (mes), <code>dd</code> (día).</div>
    </div>
  </div>

  <div id="f6" class="inner-section">
    <div class="card">
      <div class="card-title">Errores comunes con fechas</div>
      <pre><span class="cm">// INCORRECTO — comparar fechas con ==</span>
LocalDate f1 = LocalDate.of(<span class="num">2005</span>, <span class="num">12</span>, <span class="num">25</span>);
LocalDate f2 = LocalDate.of(<span class="num">2005</span>, <span class="num">12</span>, <span class="num">25</span>);
<span class="kw">if</span> (f1 == f2) ...  <span class="cm">// false (referencias distintas)</span>

<span class="cm">// CORRECTO — usar isEqual() o equals()</span>
<span class="kw">if</span> (f1.isEqual(f2)) ...  <span class="cm">// true</span>

<span class="cm">// INCORRECTO — olvidar que LocalDate es inmutable</span>
LocalDate fecha = LocalDate.now();
fecha.plusDays(<span class="num">1</span>);
System.out.println(fecha);  <span class="cm">// sigue siendo hoy</span>

<span class="cm">// CORRECTO — asignar el resultado</span>
fecha = fecha.plusDays(<span class="num">1</span>);</span></pre>
    </div>
  </div>
</div>

<!-- ══════════════════════════════════════════════
     TOPIC: CLASES INTERNAS
══════════════════════════════════════════════ -->
<div id="clases-internas" class="topic-section">
  <div class="inner-nav">
    <button class="inner-btn on" onclick="showInner('clases-internas','ci1',this)">Clases internas</button>
    <button class="inner-btn" onclick="showInner('clases-internas','ci2',this)">Clases anónimas</button>
    <button class="inner-btn" onclick="showInner('clases-internas','ci3',this)">Clases locales</button>
  </div>

  <div id="ci1" class="inner-section on">
    <div class="card">
      <div class="card-title">Clase interna — Miembro de la clase externa</div>
      <pre><span class="cm">// Clase externa</span>
<span class="kw">public class</span> Persona {
    <span class="kw">private</span> String nombre;
    <span class="kw">private int</span> edad;

    <span class="cm">// Clase interna — accede a miembros privados de Persona</span>
    <span class="kw">public class</span> Documento {
        <span class="kw">public</span> String generar() {
            <span class="cm">// Acceso a nombre (privado de Persona) desde clase interna</span>
            <span class="kw">return</span> <span class="str">"Persona: "</span> + nombre + <span class="str">"  Edad: "</span> + edad;
        }
    }
}

<span class="cm">// Uso</span>
Persona p = <span class="kw">new</span> Persona();
Persona.Documento doc = p.<span class="kw">new</span> Documento();  <span class="cm">// crea a través del objeto</span>
System.out.println(doc.generar());</pre>
      <div class="tip">Las clases internas (no-static) tienen acceso a todos los miembros privados de la clase externa, incluso si están privados.</div>
    </div>

    <div class="card">
      <div class="card-title">Clase interna estática</div>
      <pre><span class="cm">// La clase interna estática NO accede a miembros de instancia</span>
<span class="kw">public class</span> Persona {
    <span class="kw">private</span> String nombre;
    <span class="kw">public static final</span> String TIPO = <span class="str">"Humano"</span>;

    <span class="kw">public static class</span> DireccionPostal {
        String calle;
        <span class="kw">int</span> numero;

        <span class="kw">public</span> String mostrar() {
            <span class="cm">// Acceso a estáticos OK</span>
            <span class="kw">return</span> TIPO + <span class="str">": "</span> + calle + <span class="str">" "</span> + numero;
            <span class="cm">// Acceso a nombre NO OK (no es estático)</span>
        }
    }
}

<span class="cm">// Uso — sin necesidad de objeto externo</span>
Persona.DireccionPostal dir = <span class="kw">new</span> Persona.DireccionPostal();</pre>
    </div>
  </div>

  <div id="ci2" class="inner-section">
    <div class="card">
      <div class="card-title">Clase anónima — Define e instancia en una línea</div>
      <pre><span class="cm">// Patrón: new Interfaz() { implementación }</span>
Comparator&lt;String&gt; comparador = <span class="kw">new</span> Comparator&lt;String&gt;() {
    @Override
    <span class="kw">public int</span> compare(String s1, String s2) {
        <span class="kw">return</span> s1.compareTo(s2);
    }
};

<span class="cm">// Aplicar</span>
List&lt;String&gt; nombres = <span class="kw">new</span> ArrayList&lt;&gt;(Arrays.asList(<span class="str">"Zoe"</span>, <span class="str">"Ana"</span>, <span class="str">"Luis"</span>));
Collections.sort(nombres, comparador);  <span class="cm">// [Ana, Luis, Zoe]</span></pre>
      <div class="tip">Las clases anónimas son útiles para usar una interfaz funcional UNA SOLA VEZ. Si la usas varias veces, crea una clase normal.</div>
    </div>
  </div>

  <div id="ci3" class="inner-section">
    <div class="card">
      <div class="card-title">Clase local — Definida dentro de un método</div>
      <pre><span class="kw">public void</span> procesar() {
    <span class="cm">// Clase definida SOLO dentro de este método</span>
    <span class="kw">class</span> Calculadora {
        <span class="kw">public int</span> sumar(<span class="kw">int</span> a, <span class="kw">int</span> b) {
            <span class="kw">return</span> a + b;
        }
    }

    <span class="cm">// Usar la clase local</span>
    Calculadora calc = <span class="kw">new</span> Calculadora();
    System.out.println(calc.sumar(<span class="num">3</span>, <span class="num">5</span>));
    <span class="cm">// calc ya no existe fuera de este método</span>
}</pre>
    </div>
  </div>
</div>

<!-- ══════════════════════════════════════════════
     TOPIC: LAMBDA & STREAMS
══════════════════════════════════════════════ -->
<div id="lambda" class="topic-section">
  <div class="inner-nav">
    <button class="inner-btn on" onclick="showInner('lambda','l1',this)">Expresiones Lambda</button>
    <button class="inner-btn" onclick="showInner('lambda','l2',this)">Interfaces funcionales</button>
    <button class="inner-btn" onclick="showInner('lambda','l3',this)">Streams básicos</button>
    <button class="inner-btn" onclick="showInner('lambda','l4',this)">Operaciones Stream</button>
    <button class="inner-btn" onclick="showInner('lambda','l5',this)">Collectors</button>
  </div>

  <div id="l1" class="inner-section on">
    <div class="card">
      <div class="card-title">Expresión Lambda — Sintaxis compacta</div>
      <pre><span class="cm">// Lambda básica: (parámetros) -> expresión_o_bloque</span>
Comparator&lt;String&gt; comp1 = (s1, s2) -> s1.compareTo(s2);

<span class="cm">// Sin tipos (el compilador los deduce)</span>
Function&lt;Integer, Integer&gt; doble = n -> n * <span class="num">2</span>;

<span class="cm">// Con múltiples líneas</span>
Comparator&lt;Persona&gt; comp2 = (p1, p2) -> {
    String n1 = p1.getNombre().toUpperCase();
    String n2 = p2.getNombre().toUpperCase();
    <span class="kw">return</span> n1.compareTo(n2);
};

<span class="cm">// Sin parámetros</span>
Supplier&lt;LocalDate&gt; hoy = () -> LocalDate.now();

<span class="cm">// Un parámetro sin tipos</span>
Consumer&lt;String&gt; imprimir = s -> System.out.println(s);
Predicate&lt;Integer&gt; es_par = n -> n % <span class="num">2</span> == <span class="num">0</span>;</pre>
      <div class="tip">Las lambdas son solo azúcar sintáctico para clases anónimas. No son más eficientes, pero son más legibles.</div>
    </div>
  </div>

  <div id="l2" class="inner-section">
    <div class="card">
      <div class="card-title">Interfaces funcionales más comunes</div>
      <div class="mref">
        <div class="mref-row"><span class="mref-name">Predicate&lt;T&gt;</span><span class="mref-desc">test(T) → boolean. Comprobar condición</span></div>
        <div class="mref-row"><span class="mref-name">Function&lt;T,R&gt;</span><span class="mref-desc">apply(T) → R. Transformar de T a R</span></div>
        <div class="mref-row"><span class="mref-name">Consumer&lt;T&gt;</span><span class="mref-desc">accept(T) → void. Procesar sin devolver</span></div>
        <div class="mref-row"><span class="mref-name">Supplier&lt;T&gt;</span><span class="mref-desc">get() → T. Crear/generar un valor</span></div>
        <div class="mref-row"><span class="mref-name">Comparator&lt;T&gt;</span><span class="mref-desc">compare(T, T) → int. Comparar dos objetos</span></div>
      </div>
      <pre style="margin-top:10px"><span class="kw">import</span> java.util.function.*;

<span class="cm">// Ejemplos de uso</span>
Predicate&lt;Integer&gt; es_positivo = n -> n > <span class="num">0</span>;
<span class="kw">if</span> (es_positivo.test(<span class="num">5</span>)) System.out.println(<span class="str">"Positivo"</span>);

Function&lt;String, Integer&gt; contar_letras = s -> s.length();
System.out.println(contar_letras.apply(<span class="str">"Hola"</span>));  <span class="cm">// 4</span>

Consumer&lt;String&gt; saludar = nombre -> System.out.println(<span class="str">"Hola, "</span> + nombre);
saludar.accept(<span class="str">"Juan"</span>);</pre>
    </div>
  </div>

  <div id="l3" class="inner-section">
    <div class="card">
      <div class="card-title">Streams — Procesar colecciones de forma declarativa</div>
      <pre><span class="kw">import</span> java.util.stream.*;

<span class="cm">// Crear un stream</span>
List&lt;Integer&gt; numeros = Arrays.asList(<span class="num">1</span>, <span class="num">2</span>, <span class="num">3</span>, <span class="num">4</span>, <span class="num">5</span>);
Stream&lt;Integer&gt; stream = numeros.stream();

<span class="cm">// También desde array</span>
Integer[] arr = {<span class="num">1</span>, <span class="num">2</span>, <span class="num">3</span>};
Arrays.stream(arr).forEach(System.out::println);

<span class="cm">// Stream.of()</span>
Stream.of(<span class="str">"A"</span>, <span class="str">"B"</span>, <span class="str">"C"</span>).forEach(System.out::println);</pre>
    </div>

    <div class="card">
      <div class="card-title">Operaciones intermedias — Transforman el stream</div>
      <pre><span class="cm">// filter() — solo elementos que cumplen predicado</span>
numeros.stream()
    .filter(n -> n % <span class="num">2</span> == <span class="num">0</span>)
    .forEach(System.out::println);  <span class="cm">// 2, 4</span>

<span class="cm">// map() — transformar cada elemento</span>
numeros.stream()
    .map(n -> n * n)
    .forEach(System.out::println);  <span class="cm">// 1, 4, 9, 16, 25</span>

<span class="cm">// sorted() — ordenar</span>
numeros.stream()
    .sorted()
    .forEach(System.out::println);

<span class="cm">// distinct() — eliminar duplicados</span>
Arrays.asList(<span class="num">1</span>, <span class="num">2</span>, <span class="num">2</span>, <span class="num">3</span>).stream()
    .distinct()
    .forEach(System.out::println);  <span class="cm">// 1, 2, 3</span>

<span class="cm">// limit() — tomar N primeros</span>
numeros.stream().limit(<span class="num">3</span>).forEach(System.out::println);  <span class="cm">// 1, 2, 3</span></pre>
    </div>
  </div>

  <div id="l4" class="inner-section">
    <div class="card">
      <div class="card-title">Operaciones terminales — Producen resultado final</div>
      <pre><span class="cm">// forEach() — ejecutar para cada elemento</span>
numeros.stream().forEach(System.out::println);

<span class="cm">// count() — contar elementos</span>
<span class="kw">long</span> cantidad = numeros.stream().count();

<span class="cm">// max() / min() — valor máximo/mínimo</span>
Optional&lt;Integer&gt; maximo = numeros.stream().max(Integer::compareTo);
<span class="kw">if</span> (maximo.isPresent()) System.out.println(maximo.get());

<span class="cm">// anyMatch() / allMatch() / noneMatch()</span>
<span class="kw">boolean</span> hay_pares = numeros.stream().anyMatch(n -> n % <span class="num">2</span> == <span class="num">0</span>);
<span class="kw">boolean</span> todos_positivos = numeros.stream().allMatch(n -> n > <span class="num">0</span>);

<span class="cm">// findFirst() / findAny()</span>
Optional&lt;Integer&gt; primero = numeros.stream().filter(n -> n > <span class="num">3</span>).findFirst();

<span class="cm">// reduce() — combinar elementos</span>
Optional&lt;Integer&gt; suma = numeros.stream().reduce((a, b) -> a + b);
System.out.println(suma.orElse(<span class="num">0</span>));  <span class="cm">// 15</span></pre>
    </div>
  </div>

  <div id="l5" class="inner-section">
    <div class="card">
      <div class="card-title">Collectors — Agrupar y agregar resultados</div>
      <pre><span class="kw">import</span> java.util.stream.Collectors;

List&lt;String&gt; palabras = Arrays.asList(<span class="str">"sol"</span>, <span class="str">"mar"</span>, <span class="str">"cielo"</span>);

<span class="cm">// toList() — recopilar en List</span>
List&lt;String&gt; mayusculas = palabras.stream()
    .map(String::toUpperCase)
    .collect(Collectors.toList());

<span class="cm">// toSet() — recopilar en Set (sin duplicados)</span>
Set&lt;Integer&gt; unicos = Arrays.asList(<span class="num">1</span>, <span class="num">1</span>, <span class="num">2</span>).stream()
    .collect(Collectors.toSet());

<span class="cm">// groupingBy() — agrupar por criterio</span>
Map&lt;Integer, List&lt;String&gt;&gt; por_longitud = palabras.stream()
    .collect(Collectors.groupingBy(String::length));
<span class="cm">// {3: [sol, mar], 5: [cielo]}</span>

<span class="cm">// summingInt() / averagingInt() — sumas y promedios</span>
List&lt;Integer&gt; nums = Arrays.asList(<span class="num">10</span>, <span class="num">20</span>, <span class="num">30</span>);
<span class="kw">int</span> suma = nums.stream().collect(Collectors.summingInt(Integer::intValue));
Double promedio = nums.stream().collect(Collectors.averagingInt(Integer::intValue));</pre>
      <div class="tip">Collectors.toList() es preferible a recopilar en una List manualmente porque es más legible y optimizado.</div>
    </div>
  </div>
</div>

