    <div class="card">
      <div class="card-title">Trampas más comunes en el examen</div>
      <pre><span class="cm">// 1. List.size() vs Array.length</span>
lista.size();        <span class="cm">// List — método()</span>
array.length;        <span class="cm">// array — propiedad</span>

<span class="cm">// 2. LocalDate es inmutable</span>
fecha.plusDays(<span class="num">1</span>);  <span class="cm">// devuelve NUEVO objeto</span>
fecha = fecha.plusDays(<span class="num">1</span>);  <span class="cm">// CORRECTO</span>

<span class="cm">// 3. Streams son de UN USO</span>
Stream&lt;Integer&gt; s = nums.stream();
s.filter(n -> n > <span class="num">5</span>).count();
s.filter(n -> n < <span class="num">10</span>).count();  <span class="cm">// ERROR — stream ya gastado</span>

<span class="cm">// 4. TreeSet requiere Comparable</span>
Set&lt;Persona&gt; personas = <span class="kw">new</span> TreeSet&lt;&gt;();  <span class="cm">// ERROR si Persona no implementa Comparable</span>

<span class="cm">// 5. Map.put devuelve valor anterior (o null)</span>
Integer anterior = mapa.put(<span class="str">"key"</span>, <span class="num">42</span>);  <span class="cm">// null si es primera vez</span>

<span class="cm">// 6. Optional.get() lanza excepción si empty</span>
Optional&lt;Integer&gt; opt = Optional.empty();
opt.get();  <span class="cm">// NoSuchElementException</span>
opt.orElse(<span class="num">0</span>);  <span class="cm">// CORRECTO — devuelve 0</span>

<span class="cm">// 7. Lambda captura variables finales</span>
<span class="kw">int</span> x = <span class="num">5</span>;
<span class="cm">// x++;  // ERROR — x debe ser effectively final</span>
Predicate&lt;Integer&gt; p = n -> n == x;  <span class="cm">// OK si x no cambia</span></pre>
